  // munge of job_DumpTable.sen

  sFileContents =
    "\""
    "\\\"munged job_DumpTable.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_DumpTable.sen -- Job Dump Table                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_DumpTable.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a valid table folder                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkDumpTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "  //sTableNm tableInUse if popTable EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table folder\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump table request (on originating node)                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dumpTable_req ( -- <R> )\n"
    "\n"
    "  LogEntry SEED_REQ\n"
    "\n"
    "  0 0 0 0 locals| pTask sTableNm sIndexNm pJob_DumpTable |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task[] to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_DumpTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table name\n"
    "  //pJob_DumpTable job.objectName@ to sTableNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  //check if we can dump the table\n"
    "  sTableNm checkDumpTable not if pJob_DumpTable ERROR_REQUEST !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // visualize\n"
    "  sTableNm find execute table.dump\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop itable folder\n"
    "  popTable\n"
    "\n"
    "  pJob_DumpTable job.notice\n"
    "\n"
    "  LogExit DONE_REQ\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: dumptable :: dumptable <tableNm> ;\n"
    "jobSyntax: dumptable :: dumptbl <tableNm> ;\n"
    "\n"
    "jobInfo: dumptable\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_LOCAL\n"
    "  <rspKind>  = RS_JOB_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_READ\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_DumpTable.sen"_Stz
  ;

