  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_AnalyzeIndex.sen

  sFileContents =
    "\""
    "\\\"munged job_AnalyzeIndex.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_AnalyzeIndex.sen -- Job Analyze Index                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_AnalyzeIndex.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a analyzable table folder                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkAnalyzeIndex ( \\\"<tableNm>\\\" \\\"<indexNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sIndexNm sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  sIndexNm checkIsIndex not if\n"
    "    popIndexes popTable                                            // ../tables\n"
    "    assertInTables false exit\n"
    "  then\n"
    "\n"
    "  //pop indexes folder\n"
    "  popIndexes\n"
    "\n"
    "  // pop table folder\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* analyze index request (on originating node)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex::request _eeh ( -- <R> )\n"
    "\n"
    "  \\\"<detailed>\\\" job[] job.enameset@ enameset.hasName not if\n"
    "\n"
    "    \\\"<detailed>\\\" \\\"0\\\" job[] job.enameset@ enameSet.insertStr\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    <detailed> >int 1 == if\n"
    "      \\\"(nodeName VARCHAR, partition INTEGER, buffers INTEGER, bufferLevel VARCHAR, entries INTEGER)\\\"\n"
    "    else\n"
    "      \\\"(nodeName VARCHAR, partition INTEGER, buffers INTEGER, entries INTEGER)\\\"\n"
    "    then\n"
    "    job[] job.metadata!\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_AnalyzeIndex job on a node                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex::execute _eeh ( -- )\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table\n"
    "  <tableNm> pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push indexes\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // analyze the table\n"
    "  <detailed> >int <indexNm> find execute index.analyze\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // put response in the job\n"
    "  job[] job.response!\n"
    "  grid::slots job[] job.rowsProcessed!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table\n"
    "  popTable\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_AnalyzeIndex job check resources                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex::checkResources _eeh ( -- )\n"
    "\n"
    "  //\\\"checkResources received\\\" .\n"
    "\n"
    "  \\\"<detailed>\\\" job[] job.enameset@ enameset.hasName not if\n"
    "\n"
    "    \\\"<detailed>\\\" \\\"0\\\" job[] job.enameset@ enameSet.insertStr\n"
    "  then\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if we can remove the table\n"
    "  <tableNm>\n"
    "  <indexNm> \n"
    "  checkAnalyzeIndex not if job[] ERROR_JOB !!logError exit then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "jobSyntax: analyzeIndex :: analyzeIndex <tableNm> <indexNm> ;\n"
    "jobSyntax: analyzeIndex :: analyzeIndex <tableNm> <indexNm> <detailed> ;\n"
    "jobSyntax: analyzeIndex :: anidx <tableNm> <indexNm> ;\n"
    "jobSyntax: analyzeIndex :: anidx <tableNm> <indexNm> <detailed> ;\n"
    "\n"
    "jobInfo: analyzeIndex\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_DIST2PC\n"
    "  <rspKind>  = RS_PARTICIPANT_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_READ\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_AnalyzeIndex.sen"_Stz
  ;

  vCompileConstant(sFileContents);


