  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of db_index.sen

  sFileContents =
    "\""
    "\\\"munged db_index.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_index.sen -- index related words                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" db_index.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* index is used as a kind of word to identify indexes                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an indexes folder under given named table                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeIndexes ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING INDEXES FOR TABLE \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"indexes\\\"    ( dic \\\"indexes\\\" )\n"
    "  swap         ( \\\"indexes\\\" dic )\n"
    "  :subFolder   ( )\n"
    " ;\n"
    "\n"
    ": isIndex word.category@ find: index eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create an index using name from input stream (doesnt leave index on stk)   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index:\n"
    "\n"
    "  create\n"
    "  WK_OBJECT compiler::current@ word.kind!\n"
    "  sizeof_index allot\n"
    "\n"
    "  compiler::current@ word.embObject object.magic!\n"
    "  CN_INDEX compiler::current@ word.embObject object.class!\n"
    "\n"
    "  compiler::current@ word.embObject index.init\n"
    "\n"
    "  true compiler::current@ word.embObject object.wordbody!\n"
    "  find: index compiler::current@ word.category!\n"
    "\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create an index using name on the stack (leaves index on stack)            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :index\n"
    "\n"
    "  :create\n"
    "  WK_OBJECT compiler::current@ word.kind!\n"
    "  sizeof_index allot\n"
    "\n"
    "  compiler::current@ word.embObject object.magic!\n"
    "  CN_INDEX compiler::current@ word.embObject object.class!\n"
    "\n"
    "  compiler::current@ word.embObject index.init\n"
    "\n"
    "  true compiler::current@ word.embObject object.wordbody!\n"
    "  find: index compiler::current@ word.category!\n"
    "\n"
    "  compiler::current@\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within indexes folder                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinIndexes\n"
    "  path[].currentFolder dic.name \\\"indexes\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in indexes folder                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInIndexes\n"
    "  withinIndexes if true exit then\n"
    "  EC_NOT_IN_INDEXES false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* assert top of task dictionary stack is indexes                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertInIndexes ( -- t|f )\n"
    "  withinIndexes assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is an index                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsIndex ( \\\"<indexNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  0 locals| indexPtr indexNm |\n"
    "\n"
    "  indexNm find ( indexPtr )\n"
    "  to indexPtr\n"
    "\n"
    "  indexPtr\n"
    "  not ( indexPtr bool )\n"
    "\n"
    "  if\n"
    "    EC_NO_SUCH_INDEX false ( errorCode false )\n"
    "  exit\n"
    "  then\n"
    "\n"
    "  indexPtr ( indexPtr )\n"
    "  word.category@ ( ^word )\n"
    "  find: index ( ^word ^word )\n"
    "  eql ( bool )\n"
    "  if\n"
    "    true ( true )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "\n"
    "  EC_NOT_AN_INDEX false ( errorCode false )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the index sub folder and push it onto task dictionary                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": pushIndexSub ( \\\"<indexNm>\\\" -- )\n"
    "  dup checkIsIndex not if EC_NO_SUCH_INDEX false exit then\n"
    "  find execute index.subDic path[].push\n"
    "  true\n"
    " ;\n"
    "*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the index sub folder                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popIndexSub\n"
    "  path[].discard\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the indexes folder and push it onto task dictionary                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushIndexes ( -- )\n"
    "  \\\"indexes\\\" find execute path[].push\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the indexes folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popIndexes\n"
    "  path[].discard\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make_index (invoked from makeIndex)                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": make_index ( \\\"<tableNm>\\\" \\\"<indexNm>\\\" -- )\n"
    "\n"
    "  0 0 locals| indexPtr tablePtr indexNm tableNm |\n"
    "\n"
    "  pushIndexes assert\n"
    "\n"
    "  // create the index\n"
    "  indexNm ( \\\"<indexNm>\\\" )\n"
    "  :index ( ^index )\n"
    "\n"
    "  // drop the index word\n"
    "  drop (  )\n"
    "\n"
    "  // make index columns\n"
    "  //indexNm \\\"makeIndexColumns\\\" find execute\n"
    "\n"
    "  indexNm ( \\\"<indexNm>\\\" )\n"
    "\n"
    "  // find the index\n"
    "  find execute ( ^index )\n"
    "  to indexPtr\n"
    "\n"
    "  // find the table\n"
    "  tableNm find execute\n"
    "  to tablePtr\n"
    "\n"
    "  // push the table and index\n"
    "  tablePtr indexPtr ( ^index ^table )\n"
    "\n"
    "  // set the table in the index\n"
    "  index.table! (  )\n"
    "\n"
    "  // add the index in the table\n"
    "  indexPtr tablePtr table.addIndex\n"
    "\n"
    "  popIndexes\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get size of index                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex ( \\\"<indexNm>\\\" -- \\\"<size>\\\" )\n"
    "\n"
    "  find execute ( index^ )\n"
    "\n"
    "  index.space 0 swap number.magnitude >str\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT db_index.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_statWrite.sen

  sFileContents =
    "\""
    "\\\"munged OP_statWrite.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_statWrite.sen -- Operator statWrite                                     */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_statWrite.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STARTMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": OP_statWrite_InfoSet \\\\handler\n"
    "\n"
    "  \\\"statWrite_InfoSet --- --- ---\\\" .\n"
    "\n"
    "  File0[].isNull not if\n"
    "    \\\"File not null\\\" .\n"
    "    process::quit\n"
    "  then\n"
    "/*\n"
    "  file::new to File0[]\n"
    "  \\\"/tmp/SE_Stats.csv\\\" OPEN_APPEND File0[].get file.open\n"
    "  not if\n"
    "    File0[].get file.delete assert::stack_0 EC_INVALID_FILE\n"
    "    op.pipelineJob@ ERROR_JOB !!logError\n"
    "    Operand[].delete\n"
    "    Operand[].newErrorMarker\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  operand[].get to infoset[]\n"
    "  nullptr to operand[]\n"
    "\n"
    "  InfoSet[].writeCsv\n"
    "\n"
    "  infoset[].delete\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    " File0[].get file.close\n"
    " File0[].get file.delete\n"
    " */\n"
    "\n"
    "  // open the file for writing\n"
    "  \\\"/tmp/SE_Stats.csv\\\" OPEN_APPEND op__file if\n"
    "\n"
    "    Pipein[] to infoset[]\n"
    "    nullptr to Pipein[]\n"
    "\n"
    "    InfoSet[].writeCsv\n"
    "\n"
    "    infoset[].delete\n"
    "\n"
    "    File0[].get file.close\n"
    "    File0[].get file.delete\n"
    "  then\n"
    "\n"
    "  true\n"
    "\n"
    "  stk\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for statWrite req                          (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : statWrite_req \\\\operator\n"
    " \n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  C_TDEF_LOCKSTATS op__tableDef assert StreamDef[].new\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: OP_statWrite_InfoSet ZK_INFOSET op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: statWrite :: statWrite ;\n"
    "\n"
    ": statWrite opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc>  = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_statWrite.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_CreateIndex.sen

  sFileContents =
    "\""
    "\\\"munged job_CreateIndex.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_CreateIndex.sen -- Job Create Index                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_CreateIndex.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in indexes folder                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsNotIndex ( \\\"<word>\\\" )\n"
    "\n"
    "  findInCurrent not if true exit then\n"
    "  EC_INDEX_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a makeable index                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkMakeIndex ( Job_CreateIndex --  true | errorCode false )\n"
    "\n"
    "  params| pJob_CreateIndex |\n"
    "  0 0 0 locals| sTableNm sIndexNm pTable |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table and index names\n"
    "  <tableNm> to sTableNm\n"
    "  <indexNm> to sIndexNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check there is a table folder\n"
    "  sTableNm checkIsTableFolder not if false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if max indexes already on table\n"
    "  sTableNm find execute to pTable\n"
    "  pTable table.indexCount\n"
    "  C_MAX_INDEXES == if EC_MAX_INDEXES popTable assertInTables false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push indexes\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check index already exists\n"
    "  sIndexNm checkIsNotIndex not if popIndexes popTable assertInTables false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table\n"
    "  popTable\n"
    "\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an index (run by all participants)                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeIndex ( Job_CreateIndex -- <R> )\n"
    "\n"
    "  params| pJob_CreateIndex |\n"
    "  0 0 0 0 locals| pTable pIndex sTableNm sIndexNm |\n"
    "\n"
    "  //pJob_CreateIndex job.indexName@ to sIndexNm\n"
    "  //pJob_CreateIndex job.objectName@ to sTableNm\n"
    "  <indexNm> to sIndexNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // create the index\n"
    "  sIndexNm :index drop\n"
    "\n"
    "  // find the index\n"
    "  sIndexNm find execute to pIndex\n"
    "\n"
    "  // find the table\n"
    "  sTableNm find execute to pTable\n"
    "\n"
    "  //!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n"
    "  <cmd> pTable pJob_CreateIndex IndexDef::parse locals| pIndexDef |\n"
    "  //!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // check for error while creating indexdef\n"
    "  grid::thisNode@ pJob_CreateIndex job.hasError if\n"
    "    pJob_CreateIndex DdlLock[].testDrop !!logError\n"
    "    sIndexNm :forget popIndexes popTable exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set the table in the index\n"
    "  pTable pIndex index.table!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // add the index in the table\n"
    "  pIndex pTable table.addIndex\n"
    "\n"
    "  pIndexDef pIndex index.indexDef!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // validate the unqiue index columns are a subset of the partition keys\n"
    "  pIndex index.isUnique@ if\n"
    "    pIndex index.isValidUniqueIndex\n"
    "    not if EC_INVALID_COLUMNS_UNIQUE_INDEX pJob_CreateIndex ERROR_JOB\n"
    "      popIndexes popTable exit\n"
    "    then\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // now populate the index\n"
    "  pIndex index.populate\n"
    "  not if pJob_CreateIndex ERROR_JOB popIndexes popTable\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table folder\n"
    "  popTable\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create index request (on originating node)                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": createIndex::request _eeh ( -- <R> )\n"
    "\n"
    "  job[] locals| pJob_CreateIndex |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check create index syntax\n"
    "  <cmd> IndexDef::syntax dup EC_NONE != if\n"
    "    pJob_CreateIndex ERROR_JOB !!logError\n"
    "  else\n"
    "    drop\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_CreateIndex job on each node                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": createIndex::execute _eeh ( -- )\n"
    "\n"
    "  job[] locals| pJob_CreateIndex |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // make the index\n"
    "  pJob_CreateIndex makeIndex\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // should be in tables\n"
    "  assertInTables\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_CreateIndex job check resources                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": createIndex::checkResources _eeh ( -- )\n"
    "\n"
    "  job[] locals| pJob_CreateIndex |\n"
    "  0 0 locals| sTableNm sIndexNm |\n"
    "\n"
    "  //\\\"checkResources received\\\" .\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // check if we have enough buffers\n"
    "  node::checkEnoughBuffers not if pJob_CreateIndex ERROR_JOB !!logError exit then\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // check ok to make index\n"
    "  pJob_CreateIndex checkMakeIndex not if pJob_CreateIndex ERROR_JOB !!logError exit then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "jobSyntax: createIndex :: create index <indexNm> on <tableNm> etc ;\n"
    "jobSyntax: createIndex :: create unique index <indexNm> on <tableNm> etc ;\n"
    "\n"
    "jobInfo: createIndex\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_DIST2PC\n"
    "  <rspKind>  = RS_PARTICIPANT_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_WRITE\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_CreateIndex.sen"_Stz
  ;

  vCompileConstant(sFileContents);


