  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_chunk.sen

  sFileContents =
    "\""
    "\\\"munged OP_chunk.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_chunk.sen -- Operator chunk                                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_chunk.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_PULSEMARKER ...                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": chunk_PulseMarker \\\\handler\n"
    "\n"
    "  0 locals| iRowSize |\n"
    "\n"
    "  //\\\"Operand:- ZK_PULSEMARKER\\\" .verbose\n"
    "  Pipein[].pipeOut\n"
    "\n"
    "  // find the __seekOffsets table\n"
    "  C_TDEF_SEEKOFFSETS op__tableDef assert\n"
    "\n"
    "  // create a new streamDef\n"
    "  StreamDef[].new\n"
    "\n"
    "  // get row size from streamDef\n"
    "  StreamDef[].rowSize to iRowSize\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  StreamDef[].pipeout\n"
    "\n"
    "  // set eof location in counter0\n"
    "  File0[].getEofLocation to counter1[]\n"
    "\n"
    "  // set chunk location in counter1 to 0\n"
    "  0 to counter0[]\n"
    "\n"
    "  begin\n"
    "    counter1[] counter0[] >\n"
    "  while\n"
    "    // create an infoSet operand\n"
    "    iRowSize InfoSet[].newInfoSet\n"
    "    InfoSet[].chunkFile\n"
    "    InfoSet[].pipeOut\n"
    "  repeat\n"
    "\n"
    "  nullptr to Operand[]\n"
    "\n"
    "  // send EOSMARKER\n"
    "  Operand[].newEosMarker\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_STARTMARKER ...                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": chunk_StartMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STARTMARKER\\\" .verbose\n"
    "\n"
    "  // open the file for reading\n"
    "  <fileNm> OPEN_READ op__file if\n"
    "    Pipein[].pipeout\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_EXITMARKER ...                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": chunk_ExitMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_EXITMARKER\\\" .verbose\n"
    "  File0[].isNull not if\n"
    "    File0[].get file.close\n"
    "    File0[].get file.delete\n"
    "  then\n"
    "\n"
    "  Pipein[].pipeOut\n"
    "  Op.ackPipelineJob\n"
    "\n"
    "  false\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for chunk req                              (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : Chunk_req \\\\operator\n"
    " \n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: chunk_PulseMarker ZK_PULSEMARKER op[].handler!\n"
    "  find: chunk_StartMarker ZK_STARTMARKER op[].handler!\n"
    "  find: chunk_ExitMarker  ZK_EXITMARKER  op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: Chunk :: Chunk <fileNm> ;\n"
    "\n"
    ": Chunk opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_chunk.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_Universal.sen

  sFileContents =
    "\""
    "\\\"munged job_Universal.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Universal.sen -- Universal Job                                         */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Universal.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* translate seed ename, find word matching translated value and execute it   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .executeSeed params| sSeedWordNm |\n"
    "\n"
    "  // find the word mathcing the seed name\n"
    "  sSeedWordNm find locals| pWord |\n"
    "\n"
    "  pWord not if\n"
    "    sSeedWordNm \\\"Unable to find seed word: %v\\\" .printf\n"
    "    process::quit\n"
    "  then\n"
    "\n"
    "  // execute the word\n"
    "  pWord execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    ": bClusterStarted\n"
    "  grid::started@ if\n"
    "    true\n"
    "  else\n"
    "    EC_CLUSTER_NOT_CONNECTED false\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the job's request seed-word on originating node                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": universal_req ( -- <R> )\n"
    "\n"
    "  job::</seeFlow/>\n"
    "\n"
    "  \\\"<preCheck>\\\" job[] job.enameSet@ enameSet.hasName if\n"
    "    <preCheck> find execute not if\n"
    "      task::seedInitially task::doneFinally\n"
    "      job[] ERROR_JOB\n"
    "    then\n"
    "  then\n"
    "\n"
    "  <SeedReq> .executeSeed\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the job's begin seed-word on each participating node               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": universal_beg ( -- )\n"
    "\n"
    "  job::</seeFlow/>\n"
    "\n"
    "  <SeedRcv> .executeSeed\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the job's execute seed-word on each participating node             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": universal_exe ( pJob_Universal -- )\n"
    "\n"
    "  job::</seeFlow/>\n"
    "\n"
    "  <SeedExe> .executeSeed\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the job's end seed-word on each participating node                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": universal_end ( -- )\n"
    "\n"
    "  job::</seeFlow/>\n"
    "\n"
    "  <SeedEnd> .executeSeed\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the job's cancel seed-word on each participating node              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": universal_can ( -- )\n"
    "\n"
    "  job::</seeFlow/>\n"
    "\n"
    "  <SeedCan> .executeSeed\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the job's run seed-word on each participating node                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": universal_run ( -- )\n"
    "\n"
    "  job::</seeFlow/>\n"
    "\n"
    "  <SeedRun> .executeSeed\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Universal.sen"_Stz
  ;

  vCompileConstant(sFileContents);


