    "  find: ToCrw_EosMarker   ZK_EOSMARKER   op[].handler!\n"
    "  find: ToCrw_PulseMarker ZK_PULSEMARKER op[].handler!\n"
    "  find: ToCrw_StartMarker ZK_STARTMARKER op[].handler!\n"
    "  find: ToCrw_StreamDef   ZK_STREAMDEF   op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: ToCrw :: ToCrw <tableNm> ;\n"
    "\n"
    ": ToCrw opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_toCrw.sen"_Stz
  ;

