    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pipeline request (on originating node)                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pipeline::request _eeh ( -- <R> )\n"
    "\n"
    "  job[] locals| pJob_pipeline |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // compile the pipeline command\n"
    "  <cmd> job_Pipeline::compile dup\n"
    "  EC_NONE != if\n"
    "    job[] ERROR_JOB !!logError exit\n"
    "  else\n"
    "    job_Pipeline::deleteDynamo\n"
    "    drop\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_Pipeline job on a node                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pipeline::execute _eeh ( -- )\n"
    "\n"
    "  task[] locals| pTask |\n"
    "  job[]  locals| pJob_pipeline |\n"
    "\n"
    "\n"
    "  // run <pre_execute>\n"
    "\n"
    "  \\\"<pre_execute>\\\"\n"
    "  job[] job.enameSet@ enameSet.hasName if\n"
    "    \\\"<pre_execute>\\\"\n"
    "    job[] job.enameSet@ enameSet.getStr locals| sPreExe |\n"
    "    sPreExe find\n"
    "    dup not if\n"
    "      sPreExe \\\"Unable to find pre execute word: %v\\\" .printf\n"
    "      process::quit\n"
    "    then\n"
    "      execute\n"
    "  else\n"
    "    <pipelineNm> \\\"No pre execute word for pipeline: %v\\\" .printf\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab the task lock\n"
    "  pTask task.grabLock\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // execute the pipeline job (send startmarker to startOp)\n"
    "  <pipelineNm> \\\"%v execute\\\" .printf\n"
    "  pJob_pipeline job_Pipeline.execute if\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // wait for operators to finish\n"
    "    <pipelineNm> \\\"%v waiting on task::wait\\\" .printf\n"
    "    task::wait\n"
    "    <pipelineNm> \\\"%v running\\\" .printf\n"
    "\n"
    " then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_pipeline job check resources                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pipeline::checkResources _eeh ( -- )\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // compile the pipeline command\n"
    "  <cmd> job_Pipeline::compile\n"
    "  EC_NONE == assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // begin the pipeline job (spawning jobs for ops etc)\n"
    "  job[] job_Pipeline.begin\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: pipeline :: pipeline <pipelineNm> etc ;\n"
    "\n"
    "jobInfo: pipeline\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_DIST2PC\n"
    "  <rspKind>  = RS_PARTICIPANT_ERROR\n"
    "  <ddlLock>  = DL_GRAB_READ\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Pipeline.sen"_Stz
  ;

  vCompileConstant(sFileContents);


