  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_periodic.sen

  sFileContents =
    "\""
    "\\\"munged OP_periodic.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_periodic.sen -- Operator periodic                                       */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_periodic.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_ERRORMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": periodicOp_ErrorMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_ERRORMARKER\\\" .verbose\n"
    "  Pipein[].delete\n"
    "  Operand[].newExitMarker\n"
    "  Operand[].pipeOut\n"
    "  Op.ackPipelineJob\n"
    "\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_PULSEMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": periodicOp_PulseMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_PULSEMARKER\\\" .verbose\n"
    "  Pipein[].pipeOut\n"
    "\n"
    "   Counter1[] if\n"
    "    begin\n"
    "      begin\n"
    "         Counter1[]  Counter0[] >\n"
    "      while\n"
    "        task::yield\n"
    "        assert::stack_0\n"
    "        \\\"sleeping for 1 min\\\" .\n"
    "        60 task::sleepSsec\n"
    "        Counter0[] 1 + to Counter0[]\n"
    "      repeat\n"
    "      0 to  Counter0[]\n"
    "       Counter1[] \\\"Sending PULSEMARKER after %v mins\\\" str.format .\n"
    "      Operand[].newPulseMarker\n"
    "      Operand[].pipeOut\n"
    "      true\n"
    "    while assert::stack_0 repeat\n"
    "  then\n"
    "\n"
    "  Operand[].newPulsedMarker\n"
    "  Operand[].pipeOut\n"
    "  //Op.ackPipelineJob\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for periodicOp request                     (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : periodicOp_req \\\\operator\n"
    " \n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  0 locals| hours   |\n"
    "  0 locals| minutes |\n"
    "\n"
    "  \\\"<minutes>\\\" job[] job.enameset@ enameset.hasName if\n"
    "    <minutes> >int to minutes\n"
    "  then\n"
    "\n"
    "  \\\"<hours>\\\" job[] job.enameset@ enameset.hasName if\n"
    "    <hours> >int to hours\n"
    "  then\n"
    "\n"
    "  hours if\n"
    "    hours 60 * to minutes\n"
    "  then\n"
    "\n"
    "  // elapsed\n"
    "  0 to Counter0[]\n"
    "\n"
    "  // minutes\n"
    "  minutes to Counter1[]\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: periodicOp_ErrorMarker ZK_ERRORMARKER op[].handler!\n"
    "  find: periodicOp_PulseMarker ZK_PULSEMARKER op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: periodicOp :: periodicOp once ;\n"
    "opSyntax: periodicOp :: periodicOp min <minutes> ;\n"
    "opSyntax: periodicOp :: periodicOp hour <hours> ;\n"
    "\n"
    ": periodicOp opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_periodic.sen"_Stz
  ;

