    ": strVec::toPath ( s s s... n -- s )\n"
    "\n"
    "  // push initial result string\n"
    "  \\\"\\\" swap\n"
    "\n"
    "  ( n ) 0 ?do\n"
    "\n"
    "    \\\"/\\\" str.cat\n"
    "\n"
    "    swap str.cat\n"
    "\n"
    "  loop\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT vocab_str.sen"_Stz
  ;

