  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_toCrwH.sen

  sFileContents =
    "\""
    "\\\"munged OP_toCrwH.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_toCrwH.sen -- Operator toCrwH                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_toCrwH.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_PULSEMARKER ...                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": toCrwH_PulseMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_PULSEMARKER\\\" .verbose\n"
    "\n"
    "  // create a loader\n"
    "  Loader[].create\n"
    "\n"
    "  // pipe out the pulsemarker\n"
    "  Pipein[].pipeOut\n"
    "\n"
    "  // pipe out the stream def\n"
    "  Operand[].newStreamDef\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_CSVBUFFER ...                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": toCrwH_CsvBuffer \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_CSVBUFFER\\\" .verbose\n"
    "\n"
    "  Pipein[] to Operand[]\n"
    "  nullptr to Pipein[]\n"
    "\n"
    "  // use extractRow from register0 and convert csvtoCrw\n"
    "  Operand[].csvToCrwH\n"
    "\n"
    "  // pipe out any full buffers\n"
    "  grid::partitions 0\n"
    "  do\n"
    "    I loader[].fullCrwBuffer@ to OperandB[]\n"
    "\n"
    "    begin\n"
    "      OperandB[].isNull not\n"
    "    while\n"
    "      OperandB[].appendClose\n"
    "      OperandB[].pipeOut\n"
    "      I loader[].fullCrwBuffer@ to OperandB[]\n"
    "    repeat\n"
    "  loop\n"
    "\n"
    "  Operand[].delete\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_EOSMARKER ...                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": toCrwH_EosMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_EOSMARKER\\\" .verbose\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pipe out any dangling buffers\n"
    "\n"
    "  grid::partitions 0\n"
    "  do\n"
    "    I loader[].crwBuffer@ to OperandB[]\n"
    "    OperandB[].isNull not if\n"
    "      OperandB[].appendClose\n"
    "      OperandB[].pipeOut\n"
    "      nullptr I loader[].crwBuffer!\n"
    "    then\n"
    "  loop\n"
    "\n"
    "  // delete loader\n"
    "  loader[].delete\n"
    "\n"
    "  Pipein[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_STARTMARKER ...                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": toCrwH_StartMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STARTMARKER\\\" .verbose\n"
    "\n"
    "  <tableNm> locals| sTableNm |\n"
    "\n"
    "  // check if we can scan the table\n"
    "  <tableNm> op__table if\n"
    "    Pipein[].pipeout\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for toCrw req                              (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : toCrwH_req \\\\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: toCrwH_CsvBuffer   ZK_CSVBUFFER   op[].handler!\n"
    "  find: toCrwH_EosMarker   ZK_EOSMARKER   op[].handler!\n"
    "  find: toCrwH_PulseMarker ZK_PULSEMARKER op[].handler!\n"
    "  find: toCrwH_StartMarker ZK_STARTMARKER op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: toCrwH :: toCrwH <tableNm> ;\n"
    "\n"
    ": toCrwH opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_toCrwH.sen"_Stz
  ;

  vCompileConstant(sFileContents);


