  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_readChunk.sen

  sFileContents =
    "\""
    "\\\"munged OP_readChunk.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_readChunk.sen -- Operator readChunk                                     */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_readChunk.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_INFOSET ...                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": readChunk_InfoSet \\\\handler\n"
    "\n"
    "  Pipein[] to InfoSet[]\n"
    "  nullptr to Pipein[]\n"
    "\n"
    "  InfoSet[].firstRow to row[]\n"
    "  begin\n"
    "    row[].isNull\n"
    "  not while\n"
    "    row[].get InfoSet[].readChunk to Operand[]\n"
    "    Operand[].pipeout\n"
    "    InfoSet[].nextRow to row[]\n"
    "  repeat\n"
    "\n"
    "  InfoSet[].delete\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_STARTMARKER ...                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": readChunk_StartMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STARTMARKER\\\" .verbose\n"
    "\n"
    "  // open the file for reading\n"
    "  <fileNm> OPEN_READ op__file if\n"
    "    Pipein[].pipeout\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_EXITMARKER ...                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": readChunk_ExitMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_EXITMARKER\\\" .verbose\n"
    "  File0[].isNull not if\n"
    "    File0[].get file.close\n"
    "    File0[].get file.delete\n"
    "  then\n"
    "  Pipein[].pipeOut\n"
    "  Op.ackPipelineJob\n"
    "\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for reachChunk req                        (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : readChunk_req \\\\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: readChunk_InfoSet     ZK_INFOSET     op[].handler!\n"
    "  find: readChunk_StartMarker ZK_STARTMARKER op[].handler!\n"
    "  find: readChunk_ExitMarker  ZK_EXITMARKER  op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: readChunk :: readChunk <fileNm> ;\n"
    "\n"
    ": readChunk opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_readChunk.sen"_Stz
  ;

