    "    assert::stack_0\n"
    "  repeat\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STREAMDEF ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ToCsv_StreamDef \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STREAMDEF\\\" .verbose\n"
    "  Pipein[].delete\n"
    "  StreamDef[].newToCsvStream\n"
    "  StreamDef[].pipeout\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for ToCsv req                              (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : ToCsv_req \\\\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: ToCsv_CrwBuffer  ZK_CRWBUFFER op[].handler!\n"
    "  find: ToCsv_StreamDef  ZK_STREAMDEF op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: ToCsv :: ToCsv ;\n"
    "\n"
    ": ToCsv opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_toCsv.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_truncate.sen

  sFileContents =
    "\""
    "\\\"munged OP_truncate.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_truncate.sen -- Operator truncate                                       */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_truncate.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_PULSEMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": TruncateOp_PulseMarker \\\\handler\n"
    "\n"
    "\n"
    "  //\\\"Operand:- ZK_PULSEMARKER\\\" .verbose\n"
    "  Pipein[].pipeOut\n"
    "\n"
    "  // new a stream def\n"
    "  //Operand[].newStreamDef\n"
    "  //Operand[].pipeOut\n"
    "\n"
    "  // truncate the buffers of the tablePtn\n"
    "  tablePtn[].truncate\n"
    "/*\n"
    "  Subset[]@ to Operand[]\n"
    "  begin\n"
    "    Operand[].isNull\n"
    "  not while\n"
    "    Operand[].pipeOut\n"
    "    Subset[].nextBuffer to Operand[]\n"
    "  repeat\n"
    "*/\n"
    "  Operand[].newEosMarker\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STARTMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": TruncateOp_StartMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STARTMARKER\\\" .verbose\n"
    "\n"
    "  // check if we can scan the table\n"
    "  <tableNm> op__table if\n"
    "    table[].tablePtn@ to tablePtn[]\n"
    "    Pipein[].pipeOut\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for TruncateOp req                         (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : TruncateOp_req \\\\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: TruncateOp_PulseMarker ZK_PULSEMARKER op[].handler!\n"
    "  find: TruncateOp_StartMarker ZK_STARTMARKER op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: truncateOp :: truncateOp <tableNm> ;\n"
    "\n"
    ": truncateOp opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc>  = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_truncate.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of jobWords.sen

  sFileContents =
    "\""
    "\\\"munged jobWords.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* jobWords.sen -- Job related words                                          */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" jobWords.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set dictionary path of this task back into session                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": setPath ( -- )\n"
    "\n"
    "  // copy the path from task dic stack onto data stack\n"
    "  path[].depth 0 ?do\n"
    "    path[].depth 1 - I - path[].pick dic.name\n"
    "  loop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // store path into the sessions <path>=<...>\n"
    "  path[].depth strVec::toPath to /session <path>\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* job becomes a participant on participant node                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job.becomeParticipant ( pJob -- )\n"
    "\n"
    "  params| pJob |\n"
    "\n"
    " //   grid::thisNode@\n"
    " //   pJob object.class@ class::name\n"
    " //   \\\"Participant Job %v Received Node %v \\\"\n"
    " // .printf\n"
    "\n"
    "  // set participant node in job\n"
    "  grid::thisNode@ pJob job.participant!\n"
    "\n"
    "  // add job as participant job\n"
    "  pJob job.addParticipant\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* job becomes a participant on participant node                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::becomeParticipant ( -- )\n"
    "\n"
    "  job[] locals| pJob |\n"
    "\n"
    "  // set participant node in job\n"
    "  grid::thisNode@ pJob job.participant!\n"
    "\n"
    "  // add job to participant job list\n"
    "  pJob job.addParticipant\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begun a job on participant node                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::participantBegun ( -- )\n"
    "\n"
    "  job[] locals| pJob |\n"
    "\n"
    "  // send job__begun back to originating node\n"
    "  pJob \\\"Job__Begun::send\\\" find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* ended a job on participant node                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::participantEnded ( -- )\n"
    "\n"
    "  job[] locals| pJobParticipant |\n"
    "\n"
    "  pJobParticipant job.removeParticipant\n"
    "\n"
    "  pJobParticipant \\\"Job__Ended::send\\\" find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancelled a job on participant node                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::participantCancelled ( -- )\n"
    "\n"
    "  job[] locals| pJobParticipant |\n"
    "\n"
    "  pJobParticipant job.removeParticipant\n"
    "\n"
    "  pJobParticipant \\\"Job__Cancelled::send\\\" find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if this job has </flow/> and if so print the jobs ename set           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::</seeXfer/>\n"
    "\n"
    "  \\\"</xfer/>\\\"\n"
    "  job[] job.enameSet@ enameSet.hasName\n"
    "  if\n"
    "\n"
    "   r@ locate .\n"
    "   job[] job.enameSet@ enameSet.asStr .\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* delete this task's job (it's completed)                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::deleteThis ( -- )\n"
    "\n"
    "  0 locals| pThisTask |\n"
    "  0 locals| pThisJob  |\n"
    "\n"
    "  // get this task and job\n"
    "  task[] to pThisTask\n"
    "  pThisTask task.job@ to pThisJob\n"
    "\n"
    "  // now delete the ended job\n"
    "  nullptr pThisTask task.job!\n"
    "\n"
    "  //pThisJob job.id@ pThisJob \\\"job::deleteThis %v %v\\\" .printf\n"
    "\n"
    "  pThisJob job.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* call Job__Executed::send for the current job                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::participantExecuted ( pJobParticipant -- )\n"
    "\n"
    "  params| pJobParticipant  |\n"
    "\n"
    "  pJobParticipant \\\"Job__Executed::send\\\" find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* print job notice                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job.notice ( pJob -- )\n"
    "\n"
    "  params| pJob |\n"
    "\n"
    " //   pJob job.participant@\n"
    " //   pJob job.Id@\n"
    " //   pJob object.class@ class::name\n"
    " // \\\"NOTICE: %v jobId %v executed on node %v\\\" .printf\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send job (to the node which is in task)                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job.send ( pJob -- )\n"
    "\n"
    "  params| pJob |\n"
    "\n"
    "  task::sendSocket@ locals| pSocket |\n"
    "\n"
    "  pJob job.preSend\n"
    "\n"
    "  job::</seeXfer/>\n"
    "\n"
    "  task::socketLock\n"
    "\n"
    "    pJob pSocket socket.sendObject drop\n"
    "\n"
    "    pJob job.hasOperand if\n"
    "      //\\\"job.send: Job has crs buffer\\\" .\n"
    "       pJob job.operand@ pSocket socket.sendObject drop\n"
    "    then\n"
    "\n"
    "  task::socketUnlock\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send job to given participating node                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job.forward ( i_Node pJob -- )\n"
    "\n"
    "  params| pJob |\n"
    "  params| i_Node |\n"
    "\n"
    "  i_Node grid::node task[] task.sendNode!\n"
    "\n"
    "  pJob job.send\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send job back to originating node                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job.reply ( i_Node pJob -- )\n"
    "\n"
    "  params| pJob |\n"
    "  params| i_Node |\n"
    "\n"
    "  i_Node grid::node task[] task.sendNode!\n"
    "\n"
    "  pJob job.send\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add this job into originator list                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::becomeOriginator ( -- )\n"
    "\n"
    "   // set originating task\n"
    "  task[] job[] job.originatingTask!\n"
    "\n"
    "  job[] job.id@ job[] job.originatingId!\n"
    "\n"
    "  // add job to originator jobs\n"
    "  job[] job.addOriginator\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distribute the job to all participating nodes                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job.distribute ( pJob -- )\n"
    "\n"
    "  params| pJob |\n"
    "\n"
    "  // set originating task\n"
    "  task[] pJob job.originatingTask!\n"
    "\n"
    "  job[] job.id@ job[] job.originatingId!\n"
    "\n"
    "  // add job to originator jobs\n"
    "  pJob job.addOriginator\n"
    "\n"
    "  // create the response vector in the orginating job to receive responses\n"
    "  pJob job.createResponseVec\n"
    "\n"
    "  // create the buffer queue in the orginating job to receive buffers\n"
    "  pJob job.createBufferQueue\n"
    "\n"
    "  // set the no of acks expected in originator job to nodes in the grid\n"
    "  grid::connectedNodes pJob job.acksRemaining!\n"
    "\n"
    "  // grab this task's lock\n"
    "  task[] task.grabLock\n"
    "\n"
    "  // set acks for originator task\n"
    "  1 task::acks!\n"
    "\n"
    "  // send the job to each node in the grid\n"
    "  grid::definedNodes 0 do\n"
    "\n"
    "    I grid::node node.sendSocket@ if\n"
    "      I pJob job.forward\n"
    "    then\n"
    "\n"
    "  loop\n"
    "\n"
    "  // wait for ack from deciding job__Ended\n"
    "  task::wait\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::acquireDdlLock\n"
    "\n"
    "  \\\"<ddlLock>\\\" <jobNm> findJobClassEnmSet EnameSet.getInt\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  dup DL_GRAB_WRITE\n"
    "  == if\n"
    "    drop\n"
    "    // \\\"job::acquireDdlLock - grabbing ddl write lock\\\" .\n"
    "    DdlLock[].grabWrite\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  dup DL_GRAB_READ\n"
    "  == if\n"
    "    drop\n"
    "    // \\\"job::acquireDdlLock - grabbing ddl read lock\\\" .\n"
    "    DdlLock[].grabRead\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if this job has </flow/> and if so print the jobs ename set           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::</seeFlow/>\n"
    "\n"
    "  \\\"</flow/>\\\"\n"
    "    job[] job.enameSet@ enameSet.hasName\n"
    "  if\n"
    "\n"
    "    r@ locate .\n"
    "    job[] job.enameSet@ enameSet.asStr .\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT jobWords.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job__Executed.sen

  sFileContents =
    "\""
    "\\\"munged job__Executed.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job__Executed.sen -- generic job related words                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job__Executed.sen\\\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on participating node                           //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send Job__Executed back to originating node                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__Executed::send ( pJobParticipant -- )\n"
    "\n"
    "  params| pJobParticipant |\n"
    "\n"
    "  pJobParticipant job.id@ locals| iJobId |\n"
    "\n"
    "  0 0 0 locals| pJob pJob__Executed error |\n"
    "\n"
    "  // new a temporary Job__Executed\n"
    "  pJobParticipant job__Executed::new to pJob__Executed\n"
    "\n"
    "  // get error if any\n"
    "  grid::thisNode@ pJobParticipant job.error@ to error\n"
    "\n"
    "  error EC_NONE == if\n"
    "    // get the response from participant job and set it in executed job\n"
    "    pJobParticipant job.response@ pJob__Executed job.response!\n"
    "\n"
    "    // get the no of rows processed from participant job and set it in executed job\n"
    "    grid::thisNode@\n"
    "      pJobParticipant job.rowsProcessed@\n"
    "      pJob__Executed  job.rowsProcessed!\n"
    "\n"
    "    grid::thisNode@\n"
    "      pJobParticipant job.rowsInvalid@\n"
    "      pJob__Executed  job.rowsInvalid!\n"
    "\n"
    "    grid::thisNode@\n"
    "      pJobParticipant job.rowsSkipped@\n"
    "      pJob__Executed  job.rowsSkipped!\n"
    "  else\n"
    "     // set error in executed job\n"
    "     error pJob__Executed job.error!\n"
    "  then\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // set the originator node as the send target node\n"
    "  //iJobId job::originator@ grid::node task[] task.sendNode!\n"
    "\n"
    "  // send the executed job\n"
    "  iJobId job::originator@ pJob__Executed job.reply\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  pJob__Executed job.delete\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on originating node                             //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* run received Job__Executed on originating node                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _Executed _run\n"
    "\n"
    "  job[] locals| pJob__Executed |\n"
    "  pJob__Executed job.id@ locals| iJobId |\n"
    "\n"
    "  0 0 0 locals| iParticipantNode error bAmDecider |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the context of this __executed job\n"
    "\n"
    "  // find the originating job\n"
    "  iJobId olist::findJob drop\n"
    "\n"
    "  // get the participant node from where this job__begun started\n"
    "  pJob__Executed job.participant@ to iParticipantNode\n"
    "\n"
    "  // set the participant response in the originator job\n"
    "  //pJob__Executed iParticipantNode JobRef[] job.participantResponse!\n"
    "  pJob__Executed JobRef[] job.participantResponse!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // process __executed job on this originating node\n"
    "\n"
    "  // increment the number of __executed jobs received in api state\n"
    "  JobRef[] ssn::incExecuted\n"
    "  JobRef[] ssn::traceSession\n"
    "\n"
    "  // decrement the acks remaining\n"
    "  JobRef[] job.dec2pcAcksRmg to bAmDecider\n"
    "\n"
    "  // if there are acks remaining just exit\n"
    "  bAmDecider not if\n"
    "    JobRef[].return\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // all __executed jobs have been received, so this job is the decider\n"
    "\n"
    "  JP_EXECUTED log::markPhase\n"
    "\n"
    "  // send a job__end to all participants\n"
    "  JobRef[] Job__End::distribute\n"
    "  JobRef[].return\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: _Executed :: _Executed ;\n"
    "\n"
    "jobInfo: _Executed\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_GENERIC\n"
    "}\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job__Executed.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_ListIdxColumns.sen

  sFileContents =
    "\""
    "\\\"munged job_ListIdxColumns.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_ListColumns.sen -- Job list Columns                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_ListIdxColumns.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list columns of an index on a table                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listIdxColumns ( \\\"<indexNm>\\\" Job_ListIdxColumns -- )\n"
    "\n"
    "  params|  pJob_ListIdxColumns sIndexNm |\n"
    "\n"
    "  0 0 0 locals| pColumn iColumns pIndex |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get index\n"
    "  sIndexNm find execute to pIndex\n"
    "\n"
    "  pIndex index.columnCount@ to iColumns\n"
    "\n"
    "  \\\"\\\"                             // initial ls string\n"
    "  iColumns 0 do\n"
    "    I pIndex index.column@ to pColumn\n"
    "    pColumn column.isPartitionKey@\n"
    "    pColumn column.isNullable@\n"
    "    pColumn column.Scale@\n"
    "    pColumn column.Length@\n"
    "    pColumn column.type@\n"
    "    pColumn column.name@\n"
    "    \\\"row: ( '%v','%v',%v,%v,%v,%v )\\\\n\\\" str.format\n"
    "    str.cat\n"
    "  loop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set response in the job\n"
    "  pJob_ListIdxColumns job.response!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // sent rows Processed in the job\n"
    "  iColumns pJob_ListIdxColumns job.rowsProcessed!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* List Index Columns requests (on the originating node)                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lsidxcol_req ( -- <R> )\n"
    "\n"
    "  LogEntry SEED_REQ\n"
    "\n"
    "  0 0 0 0 locals| sTableNm sIndexNm pJob_ListIdxColumns pTask |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task[] to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_ListIdxColumns\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab ddl read lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if pJob_ListIdxColumns ERROR_REQUEST !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get table name from job\n"
    "  //pJob_ListIdxColumns job.objectName@ to sTableNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if pJob_ListIdxColumns ERROR_REQUEST !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is a table\n"
    "  sTableNm checkIsTable not if popTable pJob_ListIdxColumns ERROR_REQUEST !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get index name from job\n"
    "  //pJob_ListIdxColumns job.indexName@ to sIndexNm\n"
    "  <indexNm> to sIndexNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is an index\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "    popIndexes popTable assertInTables pJob_ListIdxColumns ERROR_REQUEST !!logError exit\n"
    "  then\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(columnName VARCHAR, columnType VARCHAR, columnLength INTEGER, columnScale INTEGER, isNull boolean, isPartitionKey boolean)\\\"\n"
    "        pJob_ListIdxColumns job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // list table columns\n"
    "  sIndexNm pJob_ListIdxColumns listIdxColumns\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes folder\n"
    "  popIndexes\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "  assertInTables\n"
    "\n"
    "  LogExit DONE_REQ\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: lsidxcol :: lsidxcol <tableNm> <indexNm> ;\n"
    "\n"
    "jobInfo: lsidxcol\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_LOCAL\n"
    "  <rspKind>  = RS_JOB_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_READ\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_ListIdxColumns.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of se_requests.sen

  sFileContents =
    "\""
    "\\\"munged se_requests.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* se_requests.sen -- requests                                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" se_requests.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* log word entry                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": LogReqEntry immediate\n"
    "\n"
    "  // format the string to be printed\n"
    "  compiler::current@ word.name@ \\\">>%v\\\" str.format\n"
    "\n"
    "  // encode push of that string\n"
    "  ,\n"
    "\n"
    "  // encode call to markEntry\n"
    "  POSTPONE Log::markEntry\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* log word exit                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": LogReqExit immediate\n"
    "\n"
    "  // format the string to be printed\n"
    "  compiler::current@ word.name@ \\\"<<%v\\\" str.format\n"
    "\n"
    "  // encode push of that string\n"
    "  ,\n"
    "\n"
    "  // encode call to markExit\n"
    "  POSTPONE Log::markExit\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT se_requests.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_VisualizeTable.sen

  sFileContents =
    "\""
    "\\\"munged job_VisualizeTable.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_VisualizeTable.sen -- Job Visualize Table                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_VisualizeTable.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a valid table folder                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkVisualizeTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "  //sTableNm tableInUse if popTable EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table folder\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* visualize table request (on originating node)                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": visualizeTable_req ( -- <R> )\n"
    "\n"
    "  LogEntry SEED_REQ\n"
    "\n"
    "  0 0 0 0 0 locals| pTask pIndex sTableNm sIndexNm pjob_VisualizeTable |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task[] to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pjob_VisualizeTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table name\n"
    "  //pjob_VisualizeTable job.objectName@ to sTableNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if we can visualize table\n"
    "  sTableNm checkVisualizeTable not if pjob_VisualizeTable ERROR_REQUEST !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // visualize \n"
    "  sTableNm find execute table.visualize\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table folder\n"
    "  popTable\n"
    "\n"
    "  pjob_VisualizeTable job.notice\n"
    "\n"
    "  LogExit DONE_REQ\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: visualizeTable :: vistbl <tableNm> ;\n"
    "\n"
    "jobInfo: visualizeTable\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_LOCAL\n"
    "  <rspKind>  = RS_JOB_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_READ\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_VisualizeTable.sen"_Stz
  ;

  vCompileConstant(sFileContents);


