  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_FetchRows.sen

  sFileContents =
    "\""
    "\\\"munged job_FetchRows.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_FetchRows.sen -- Job Fetch Rows                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_FetchRows.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate plan for the fetch                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": generatePlan ( \\\"<sWhere>\\\" ^pTable -- ^pPlanner )\n"
    "\n"
    "  0 0 locals| pPlanner pAccessPath pTable sWhere |\n"
    "\n"
    "  //sWhere \\\"generatePlan\\\" \\\"%v %v\\\" str.format .\n"
    "\n"
    "  ( cdt_0 ) planner::new to pPlanner\n"
    "  ( cdt_1 ) pTable pPlanner Planner.table!\n"
    "\n"
    "  ( cdt_2 ) sWhere pPlanner Planner.parseWhere  //\\\"parseWheres\\\" .\n"
    "\n"
    "  ( cdt_3 ) pPlanner Planner.genPaths           //\\\"genPaths\\\" .\n"
    "  ( cdt_4 ) pPlanner Planner.scorePaths         //\\\"scorePaths\\\" .\n"
    "  //( cdt_5 ) pPlanner Planner.showPaths\n"
    "\n"
    "  ( cdt_6 ) pPlanner Planner.matchPaths         //\\\"matchPaths\\\" .\n"
    "  //( cdt_6 ) pPlanner Planner.showPaths\n"
    "\n"
    "  ( cdt_7 ) pPlanner Planner.choosePaths        //\\\"choosePaths\\\" .\n"
    "\n"
    "  // return planner\n"
    "  pPlanner\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn sub fetch jobs                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnSub ( phrase planner Job_FetchRows -- )\n"
    "\n"
    "  params| pJob_FetchRows pPlanner iPhrase |\n"
    "  pJob_FetchRows job_fetchRows.partition@ locals| iFetchPartition |\n"
    "\n"
    "  -1 iFetchPartition == if\n"
    "    // spawn a subFetch job for each partition\n"
    "    grid::slots 0\n"
    "    do\n"
    "      //I \\\"Creating Job_SubFetch %v\\\" .printf\n"
    "      I iPhrase pPlanner pJob_FetchRows job_fetchRows.spawnSub\n"
    "    loop\n"
    "  else\n"
    "    // spawn a sub fetch job for given partition\n"
    "    iFetchPartition grid::toSlot iPhrase pPlanner pJob_FetchRows job_fetchRows.spawnSub\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute checkFetchRows                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkFetchRows ( \\\"<sColumnNm>\\\" \\\"<tableNm>\\\"  partition -- true | errorCode false )\n"
    "\n"
    "  params| iPartition sTableNm sColumnNm |\n"
    "  0 locals| pJob_FetchRows |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  task[] task.job@ to pJob_FetchRows\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check partition if specified (should belong to this node)\n"
    "  -1 iPartition != if\n"
    "    iPartition grid::partitions >= if EC_INVALID_PARTITION false exit then\n"
    "    iPartition grid::toNode grid::thisNode@ != if EC_INVALID_PARTITION false exit then\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check table folder exists\n"
    "  sTableNm checkIsTableFolder not if false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is a table\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // if retrieving column, check it is a valid column\n"
    "  \\\"\\\" sColumnNm str.equal not if\n"
    "    sColumnNm sTableNm checkIsColumn not if popTable false exit then\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* fetch rows table request (on originating node)                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchRows_req ( -- <R> )\n"
    "\n"
    "  LogEntry SEED_REQ\n"
    "\n"
    "  100 ssn::senLoc\n"
    "\n"
    "  0 0 0 0 locals| iPhrases sTableNm sColumnNm sWhere |\n"
    "  0 0 0 0 locals| pJob_FetchRows pTask pPlanner pTable |\n"
    "  0 locals| iFetchPartition |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task[] to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_FetchRows\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // assert correct job\n"
    "  CN_JOB_FETCHROWS pJob_FetchRows object.assertClass\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table name, column name  and partition\n"
    "  //pJob_FetchRows job.objectName@ to sTableNm\n"
    "  <tableNm> to sTableNm\n"
    "  pJob_FetchRows Job_FetchRows.columnName@ to sColumnNm\n"
    "  pJob_FetchRows job_fetchRows.partition@ to iFetchPartition\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if we can fetch rows\n"
    "  sColumnNm sTableNm iFetchPartition checkFetchRows not if pJob_FetchRows ERROR_REQUEST !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // find the table\n"
    "  sTableNm pushTable assert\n"
    "  sTableNm find execute to pTable\n"
    "  pTable pJob_FetchRows job_fetchRows.table!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // find the column from the table and set it in the fetchRows job\n"
    "  \\\"\\\" sColumnNm str.equal not if\n"
    "    sColumnNm pTable table.findColumn pJob_FetchRows job_fetchRows.column!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set the metadata string\n"
    "  args.metadata if\n"
    "    pTable table.getColumnsAsString \\\"(%v)\\\" str.format pJob_FetchRows job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the where clause from the job\n"
    "  pJob_FetchRows job_fetchRows.where@ to sWhere\n"
    "\n"
    "  400 ssn::senLoc\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // generate the plan for the fetch\n"
    "  sWhere pTable generatePlan to pPlanner\n"
    "  pPlanner pJob_FetchRows job_fetchRows.planner!\n"
    "\n"
    "  //pPlanner planner.showPaths\n"
    "\n"
    "  // assert we have a plan\n"
    "  pPlanner assert\n"
    "  pPlanner planner.phrases@ to iPhrases\n"
    "\n"
    "  -1 iFetchPartition == if\n"
    "     // set the no of last buffers to no phrases * slots in the job\n"
    "     iPhrases grid::slots * pJob_FetchRows job_fetchRows.lastBuffers!\n"
    "  else\n"
    "    // set the no of last buffers to no phrases in the job\n"
    "    iPhrases pJob_FetchRows job_fetchRows.lastBuffers!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // spawn the sub fetch jobs\n"
    "  iPhrases 0\n"
    "  do\n"
    "    I pPlanner pJob_FetchRows spawnSub\n"
    "  loop\n"
    "\n"
    "  popTable\n"
    "\n"
    "  pJob_FetchRows job.notice\n"
    "\n"
    "  900 ssn::senLoc\n"
    "\n"
    "  LogExit DONE_REQ\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_FetchRows.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
