  // munge of job_UseSchema.sen

  sFileContents =
    "\""
    "\\\"munged job_UseSchema.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_UseSchema.sen -- Job Use Schema                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_UseSchema.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* use given schema                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": useSchema ( job_UseSchema --  )\n"
    "\n"
    "  params| pJob_UseSchema |\n"
    "\n"
    "\n"
    "  // pop path till we get to tenants\n"
    "  begin\n"
    "    path[].currentFolder dic.name \\\"tenants\\\" str.equal not while path[].discard\n"
    "  repeat\n"
    "\n"
    "  // find the boray folder\n"
    "  \\\"boray\\\" findInCurrent\n"
    "  execute path[].push\n"
    "\n"
    "  // find the catalogs folder\n"
    "  \\\"catalogs\\\" findInCurrent\n"
    "  execute path[].push\n"
    "\n"
    "  // find the rapidssecatalogs folder\n"
    "  \\\"rapidsse\\\" findInCurrent\n"
    "  execute path[].push\n"
    "\n"
    "  // find the schemas folder\n"
    "  \\\"schemas\\\" findInCurrent\n"
    "  execute path[].push\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get schema name from job\n"
    "  //pJob_UseSchema job.schemaName@ to sSchemaNm\n"
    "\n"
    "  <schemaNm> checkIsWord not if EC_NO_SUCH_SCHEMA pJob_UseSchema ERROR_JOB !!logError exit then\n"
    "  checkIsSchema not if pJob_UseSchema ERROR_JOB !!logError exit then\n"
    "  execute path[].push\n"
    "\n"
    "  // find the tables folder\n"
    "  \\\"tables\\\" findInCurrent\n"
    "  execute path[].push\n"
    "\n"
    "  // save the path\n"
    "  setPath\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* Use Schema request (on the originating node)                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": useSchema_req ( -- <R> )\n"
    "\n"
    "  LogEntry SEED_REQ\n"
    "\n"
    "  0 0 locals| sSchemaNm pJob_UseSchema pTask |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task[] to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_UseSchema\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // use schema\n"
    "  pJob_UseSchema useSchema\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // return\n"
    "  LogExit DONE_REQ\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: useSchema :: use schema <schemaNm> ;\n"
    "\n"
    "jobInfo: useSchema\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_LOCAL\n"
    "  <rspKind>  = RS_JOB_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_READ\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\""
  " CONSTANT job_UseSchema.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_space.sen

  sFileContents =
    "\""
    "\\\"munged OP_space.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_space.sen -- Operator space                                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_space.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": space_action\n"
    "\n"
    "  0 locals| iRowSize |\n"
    "\n"
    "  // get row size from streamDef\n"
    "  StreamDef[].rowSize to iRowSize\n"
    "\n"
    "  // create an infoSet operand\n"
    "  iRowSize InfoSet[].newInfoSet\n"
    "\n"
    "  // add nodeInfo to the infoSet\n"
    "  StreamDef[] InfoSet[].addSpaceInfo assert\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  StreamDef[].pipeout\n"
    "\n"
    "  // pipeout the infoset\n"
    "  InfoSet[].pipeout\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: space :: space ;\n"
    "\n"
    ": space opInfo tagCopy: liteOp_tags\n"
    "  tags{\n"
    "    <jobDesc>   = \\\"--description of operator--\\\"\n"
    "    <liteOp>    = true\n"
    "    <streamDef> = __space\n"
    "  }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_space.sen"_Stz
  ;

