  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_SubLoader.sen

  sFileContents =
    "\""
    "\\\"munged job_SubLoader.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_SubLoader.sen -- Job Table SubLoader                                   */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_SubLoader.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* read records from file, create working buffers, send to node               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": SubLoader_process ( pJob_SubLoader -- )\n"
    "\n"
    "  params| pJob_SubLoader |\n"
    "\n"
    "  0 locals| bContinue |\n"
    "\n"
    "  pJob_SubLoader job_subLoader.begin not if exit then\n"
    "\n"
    "  begin\n"
    "    pJob_SubLoader job_subLoader.chunk to bContinue\n"
    "    bContinue if\n"
    "      pJob_SubLoader job_subLoader.terminate not to bContinue\n"
    "    then\n"
    "    bContinue while\n"
    "  repeat\n"
    "\n"
    "  pJob_SubLoader job_subLoader.end\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* SubLoader seed                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": subLoader_run ( -- )\n"
    "\n"
    "  LogEntry SEED_RUN\n"
    "\n"
    "  task[] locals| pThisTask |\n"
    "  job[]  locals| pJob_SubLoader |\n"
    "\n"
    "  pJob_SubLoader SubLoader_process\n"
    "\n"
    "  job::deleteThis\n"
    "  DONE_RUN\n"
    "\n"
    "  job::completed\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_SubLoader.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job__Begun.sen

  sFileContents =
    "\""
    "\\\"munged job__Begun.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job__Begun.sen -- generic job related words                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job__Begun.sen\\\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on participating node                           //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send Job__Begun back to originating node                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__Begun::send ( pJobParticipant -- )\n"
    "\n"
    "  params| pJobParticipant |\n"
    "\n"
    "  pJobParticipant job.id@ locals| iJobId |\n"
    "\n"
    "  0 0 locals| pJob__Begun error |\n"
    "\n"
    "  // new a temporary Job__Executed\n"
    "  pJobParticipant job__Begun::new to pJob__Begun\n"
    "\n"
    "  // get error if any\n"
    "  grid::thisNode@ pJobParticipant job.error@ to error\n"
    "\n"
    "  error EC_NONE != if\n"
    "    // set error in the job\n"
    "    error pJob__Begun job.error!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // set the originator node as the send target node\n"
    "  //iJobId job::originator@ grid::node task[] task.sendNode!\n"
    "\n"
    "  // send the begun job\n"
    "  iJobId job::originator@ pJob__Begun job.reply\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  pJob__Begun job.delete\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on originating node                             //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* run this received Job__Begun on originating node                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _Begun _run\n"
    "\n"
    "  //\n"
    "  // where:  On the originator node.\n"
    "  // event:  A Job__Begun has been received from a participating node\n"
    "  //         indicating the job has been received and put into the\n"
    "  //         participating jobs list.\n"
    "  // data:   The job will exist in the originating jobs list.\n"
    "  // action: 1) find the job in the originating list;\n"
    "  //         2) decrement its ack's remaining\n"
    "  //         3) if all acks received distribute Job_Execute\n"
    "  //\n"
    "\n"
    "  job[] locals| pJob__Begun |\n"
    "\n"
    "  pJob__Begun job.id@ locals| iJobId |\n"
    "\n"
    "  0 0 0 0 locals| bAmDecider error iParticipantNode |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the context of this __begun job\n"
    "\n"
    "  // find the originating job\n"
    "  iJobId olist::findJob drop\n"
    "\n"
    "  // get the participant node from where this job__begun started\n"
    "  pJob__Begun job.participant@ to iParticipantNode\n"
    "\n"
    "  // get the error code from job__begun\n"
    "  pJob__Begun job.error@ to error\n"
    "\n"
    "  error EC_NONE != if\n"
    "    // set the error code in pJobOriginator for this partcipant\n"
    "    //error iParticipantNode pJobOriginator job.error!\n"
    "    //pJob__Begun iParticipantNode pJobOriginator job.participantResponse!\n"
    "    pJob__Begun JobRef[] job.participantResponse!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // process __begun job on this originating node\n"
    "\n"
    "  // increment the number of __begun jobs received in api state\n"
    "  JobRef[] ssn::incBegun\n"
    "  JobRef[] ssn::traceSession\n"
    "\n"
    "  // decrement the acks remaining in the originating job\n"
    "  JobRef[] job.dec2pcAcksRmg to bAmDecider\n"
    "\n"
    "  // if there are acks remaining just exit\n"
    "  bAmDecider not if\n"
    "    JobRef[].return\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // all job__begun's have been received, so this job is the decider\n"
    "\n"
    "  JP_BEGUN log::markPhase\n"
    "\n"
    "  // check if any node returned an error\n"
    "  JobRef[] job.participantHasError true == if\n"
    "    // distribute Job__Cancel to all participants\n"
    "    JobRef[] Job__Cancel::distribute\n"
    "    JobRef[].return\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  JP_EXECUTING log::markPhase\n"
    "\n"
    "  // distribute Job__Execute to all participants\n"
    "  JobRef[] Job__Execute::distribute\n"
    "  JobRef[].return\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: _Begun :: _Begun ;\n"
    "\n"
    "jobInfo: _Begun\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_GENERIC\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job__Begun.sen"_Stz
  ;

  vCompileConstant(sFileContents);


