  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of BM_insIdx.sen

  sFileContents =
    "\""
    "\\\"munged BM_insIdx.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* BM_insIdx.sen -- Benchmark Operator insIdx                                 */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" BM_insIdx.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_InsIdx_Report\n"
    "\n"
    "  Operand[].newCsvBuffer\n"
    "  Operand[].report\n"
    "\n"
    "  now[] now.asOf\n"
    "\n"
    "  now[] now.timestampStr locals| sTsp |\n"
    "  now[] now.sinceEpoch   locals| iNow |\n"
    "\n"
    "  // csv report for bm_insidx\n"
    "  aggTimer[] aggTimer.reportStr\n"
    "    iNow\n"
    "    sTsp\n"
    "    \\\"BM_InsIdx,%v,%v,Elapsed Time,%v\\\\n\\\"\n"
    "    str.format Operand[].csvAppend\n"
    "\n"
    "  counter0[].get\n"
    "    iNow\n"
    "    sTsp\n"
    "    \\\"BM_InsIdx,%v,%v,Number of EntBuffers,%v\\\\n\\\"\n"
    "    str.format Operand[].csvAppend\n"
    "\n"
    "  counter1[].get\n"
    "    iNow\n"
    "    sTsp\n"
    "    \\\"BM_InsIdx,%v,%v,Total Number of Entries,%v\\\\n\\\"\n"
    "    str.format Operand[].csvAppend\n"
    "\n"
    "  aggTimer[] aggTimer.nanosecs counter1[].get /\n"
    "    iNow\n"
    "    sTsp\n"
    "    \\\"BM_InsIdx,%v,%v,Average Time per Entry,%vns\\\\n\\\"\n"
    "    str.format Operand[].csvAppend\n"
    "  \n"
    "  Operand[].pipeout\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_ENTBUFFER ...                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_InsIdx_EntBuffer \\\\handler\n"
    "\n"
    "  \\\"BM_InsIdx_EntBuffer\\\" .\n"
    "\n"
    "  // get index partition for current partition\n"
    "  index[].get index.IndexPtn to IndexPtn[] // indexPtn\n"
    "\n"
    "  BM_TimerBegin\n"
    "\n"
    "  // insert all the entries into tree\n"
    "  //   NB: registers are available in the step!!\n"
    "  Operand[].get IndexPtn[].get IndexPtn.insEntBuffer // <- focal pt of bm\n"
    "    counter1[] + to counter1[]\n"
    "\n"
    "  counter0[] 1 + to counter0[]\n"
    "\n"
    "  BM_TimerUpdate\n"
    "\n"
    "  Operand[].delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_EOSMARKER ...                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_InsIdx_EosMarker \\\\handler\n"
    "\n"
    "  Pipein[].delete\n"
    "\n"
    "  BM_InsIdx_Report\n"
    "\n"
    "  Operand[].newEosMarker\n"
    "  Operand[].pipeout\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_STARTMARKER ...                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_InsIdx_StartMarker \\\\handler\n"
    "\n"
    "  now[] now.asOf now[] now.timestampStr .\n"
    "  now[] now.sinceEpoch \\\"SinceEpoch: %vs\\\" .printf\n"
    "\n"
    "  // table index folder push\n"
    "  <tableNm> <indexNm> op__table_index if\n"
    "\n"
    "    path[].toStr \\\"Folder path: %v\\\" .printf\n"
    "\n"
    "    BM_TimerNew\n"
    "\n"
    "    //Task_Interpreter\n"
    "\n"
    "    Pipein[].pipeout\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for insIdx                                 (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_InsIdxOp_req \\\\operator\n"
    " \n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  true \\\"BM_InsIdx_StartMarker\\\" find word.breakPt!\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: BM_InsIdx_EntBuffer   ZK_ENTBUFFER   op[].handler!\n"
    "  find: BM_InsIdx_EosMarker   ZK_EOSMARKER   op[].handler!\n"
    "  find: BM_InsIdx_StartMarker ZK_STARTMARKER op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  \\\"*** BM_InsIdxOp EXITS\\\" .\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: BM_InsIdxOp :: BM_InsIdxOp <tableNm> <indexNm> ;\n"
    "\n"
    ": BM_InsIdxOp opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT BM_insIdx.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_Receiver.sen

  sFileContents =
    "\""
    "\\\"munged job_Receiver.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Receiver.sen -- receiver job                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Receiver.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn the receiver job (as a dedicated job)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawn_Receiver ( pAnsweredNode iConnNo -- )\n"
    "\n"
    "  params| iConnNo |\n"
    "  params| pAnsweredNode |\n"
    "\n"
    "  0 locals| pJobClass_Receiver |\n"
    "  0 locals| pJob_Receiver |\n"
    "\n"
    "  CN_JOB_RECEIVER jobClass::find to pJobClass_Receiver\n"
    "\n"
    "  pJobClass_Receiver jobClass.new to pJob_Receiver\n"
    "\n"
    "  iConnNo       pJob_Receiver job_receiver.connNo!\n"
    "  pAnsweredNode pJob_Receiver job_receiver.node!\n"
    "\n"
    "  pJob_Receiver JM_SEED_RUN job.spawn_dedicated\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* receiver init                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": receiver_init ( -- )\n"
    "\n"
    "  CN_JOB_RECEIVER task[] task.thread thread.dedicated!\n"
    "\n"
    "  NS_ACTIVE grid::thisNode@ grid::node node.state!\n"
    "\n"
    "  args.verbose if\n"
    "    grid::thisNode@ \\\"receiver running on node %v\\\" .printf\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* receiver loop: receive a job (possibly with operand), dispatch it          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": receiver_loop ( -- )\n"
    "\n"
    "  0 locals| pReceivedJob |\n"
    "  0 locals| pOperand     |\n"
    "  0 locals| pSendWith    |\n"
    "  0 locals| pOtherNode   |\n"
    "  0 locals| pSocket      |\n"
    "  0 locals| bRecvd       |\n"
    "\n"
    "  job[] locals| pJob_Receiver |\n"
    "\n"
    "  pJob_Receiver job_Receiver.node@ to pOtherNode\n"
    "\n"
    "  pOtherNode node.recvSocket@ to pSocket\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  begin\n"
    "\n"
    "    assertStackDepthZero\n"
    "\n"
    "    // -- -- -- -- -- -- -- --\n"
    "    // recv job\n"
    "\n"
    "    pSocket socket.recvObject\n"
    "\n"
    "    not if\n"
    "      //ifAgain\n"
    "      \\\"receiver exiting\\\" .\n"
    "      exit\n"
    "    then\n"
    "\n"
    "    to pReceivedJob\n"
    "\n"
    "    // -- -- -- -- -- -- -- --\n"
    "    // log received job\n"
    "\n"
    "    pReceivedJob job_receiver::jobReceived\n"
    "\n"
    "    // -- -- -- -- -- -- -- --\n"
    "    // run post receive function\n"
    "\n"
    "    pReceivedJob job.postRecv\n"
    "\n"
    "    // -- -- -- -- -- -- -- --\n"
    "    // recv operand\n"
    "\n"
    "    pReceivedJob job.hasOperand if\n"
    "      pSocket socket.recvObject drop to pOperand\n"
    "      pOperand pReceivedJob job.operand!\n"
    "    then\n"
    "\n"
    "    // -- -- -- -- -- -- -- --\n"
    "    // examine job\n"
    "    //pReceivedJob job.kind@ JK_GENERIC == if\n"
    "      //\\\"received a generic job\\\" .\n"
    "    //  pReceivedJob job.enameSet@ enameSet.asStr .\n"
    "    //then\n"
    "\n"
    "    // -- -- -- -- -- -- -- --\n"
    "    // dispatch job\n"
    "\n"
    "    pReceivedJob job.jobClass CN_JOB_OPERAND == if\n"
    "    //pReceivedJob job.hasOperand if\n"
    "      pReceivedJob Job_operand.pipeOut\n"
    "    else\n"
    "      pReceivedJob job.seedDecode\n"
    "      pReceivedJob job.seed!\n"
    "      pReceivedJob job.spawn\n"
    "   then\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* receiver seed                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": receiver_run ( -- )\n"
    "\n"
    "  LogEntry SEED_RUN\n"
    "\n"
    "  task[] locals| pThisTask |\n"
    "  job[]  locals| pJob_Receiver |\n"
    "\n"
    "  // initialise\n"
    "  receiver_init\n"
    "\n"
    "  // loop, receiving and executing jobs\n"
    "  receiver_loop\n"
    "\n"
    "  // should never exit\n"
    "  //hazard\n"
    "\n"
    "  job::completed\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Receiver.sen"_Stz
  ;

