  // munge of db_catalog.sen

  sFileContents =
    "\""
    "\\\"munged db_catalog.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_catalog.sen -- catalog related words                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" db_catalog.sen\\\" .verbose\n"
    "\n"
    ": catalog ;\n"
    "\n"
    ": :catalog\n"
    "    :createFolder\n"
    "         //dup find: catalog swap word.category!\n"
    "         dup find: catalog swap execute dic.kind!\n"
    " ;\n"
    "\n"
    ": withinCatalogs\n"
    "    path[].currentFolder dic.name \\\"catalogs\\\" str.equal\n"
    " ;\n"
    "\n"
    ": checkInCatalogs\n"
    "    withinCatalogs if true exit then\n"
    "    EC_NOT_IN_CATALOGS false\n"
    " ;\n"
    "\n"
    ": checkIsCatalog ( word )\n"
    "    dup word.category@ find: \\\\folder eql not if EC_NOT_A_FOLDER false exit then\n"
    "    dup execute dic.kind@ find: catalog eql if true exit then\n"
    "    EC_NOT_A_CATALOG false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a catalogs folder under given named tenant                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeCatalogs ( \\\"<tenantNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING CATALOGS FOR TENANT \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"catalogs\\\"   ( dic \\\"catalogs\\\" )\n"
    "  swap         ( \\\"catalogs\\\" dic )\n"
    "  :subFolder   ( )\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT db_catalog.sen"_Stz
  ;

  vCompileConstant(sFileContents);


