    "  Op.ackPipelineJob\n"
    "\n"
    "  false\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for toFileOp req                           (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : ToFileOp_req \\\\operator\n"
    " \n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: ToFileOp_CsvBuffer   ZK_CSVBUFFER   op[].handler!\n"
    "  find: ToFileOp_StartMarker ZK_STARTMARKER op[].handler!\n"
    "  find: ToFileOp_ExitMarker  ZK_EXITMARKER  op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: ToFileOp :: ToFileOp <fileNm> ;\n"
    "\n"
    ": ToFileOp opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc>  = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_toFile.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of db_table.sen

  sFileContents =
    "\""
    "\\\"munged db_table.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_table.sen -- table related words                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" db_table.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* table is used as a kind of word to identify tables                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table ;\n"
    "\n"
    "//: makeTables path[].push \\\"tables\\\" :dic find: folder swap execute dic.kind! path[].discard ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tables folder under given named schema                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTables ( \\\"<schemaNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING TABLES FOR SCHEMA \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"tables\\\"     ( dic \\\"tables\\\" )\n"
    "  swap         ( \\\"tables\\\" dic )\n"
    "  :subFolder   ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tableNm folder under tables                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTableDic ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING TABLE DIC \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  path[].currentFolder\n"
    "  :subFolder    ( )\n"
    " ;\n"
    "\n"
    "\n"
    ": isTable word.category@ find: table eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a table using name from input stream (doesnt leave table on stk)    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table:\n"
    "\n"
    "  createPersistent\n"
    "  WK_OBJECT compiler::current@ word.kind!\n"
    "  sizeof_table allot\n"
    "\n"
    "  compiler::current@ word.embObject object.magic!\n"
    "  CN_TABLE compiler::current@ word.embObject object.class!\n"
    "\n"
    "  compiler::current@ word.embObject table.init\n"
    "\n"
    "  true compiler::current@ word.embObject object.wordbody!\n"
    "  find: table compiler::current@ word.category!\n"
    "\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a table using name on the stack (leaves table on stack)             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :table\n"
    "\n"
    "  >createPersistent\n"
    "  WK_OBJECT compiler::current@ word.kind!\n"
    "  sizeof_table allot\n"
    "\n"
    "  compiler::current@ word.embObject object.magic!\n"
    "  CN_TABLE compiler::current@ word.embObject object.class!\n"
    "\n"
    "  compiler::current@ word.embObject table.init\n"
    "\n"
    "  true compiler::current@ word.embObject object.wordbody!\n"
    "  find: table compiler::current@ word.category!\n"
    "\n"
    "  compiler::current@\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if this task dic path ends in tables                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinTables ( -- t|f )\n"
    "\n"
    "  path[].currentFolder dic.name \\\"tables\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* assert top of task dictionary stack is tables                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertInTables ( -- t|f )\n"
    "\n"
    "  withinTables assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check top of task dictionary stack is tables                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInTables ( -- t|f )\n"
    "\n"
    "  withinTables if true exit then\n"
    "\n"
    "  EC_NOT_IN_TABLES false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if column is a valid column of the table                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsColumn ( \\\"<columnNm>\\\" \\\"<tableNm>\\\"-- t|f )\n"
    "\n"
    "  params| sTableNm sColumnNm |\n"
    "  0 locals| pTable |\n"
    "\n"
    "  sTableNm find execute to pTable\n"
    "  sColumnNm pTable table.isColumn if true exit then\n"
    "\n"
    "  EC_INVALID_COLUMN false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if this task dic path is same name as argument                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinTable ( \\\"<tableNm>\\\" -- t|f )\n"
    "\n"
    "  assert::stack_1+\n"
    "  CN_STZVAL assert::class_0\n"
    "\n"
    "  // assert dictionary path\n"
    "  path[].depth assert\n"
    "\n"
    "  path[].currentFolder dic.name str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check top of task dictionary stack is given table name                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInTable ( \\\"<tableNm>\\\" -- t|f )\n"
    "\n"
    "  withinTable if true exit then\n"
    "\n"
    "  EC_NOT_IN_TABLE false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check given name is a table                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  find ( \\\"<tableNm>\\\" ^w:table )\n"
    "\n"
    "  dup ( \\\"<tableNm>\\\" ^w:table ^w:table )\n"
    "  not ( \\\"<tableNm>\\\" ^w:table bool )\n"
    "  if\n"
    "    drop ( \\\"<tableNm>\\\" )\n"
    "    drop ( )\n"
    "    EC_NO_SUCH_TABLE false ( errorCode false )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  dup ( \\\"<tableNm>\\\" ^w:table ^w:table )\n"
    "\n"
    "  word.category@ ( \\\"<tableNm>\\\" ^w:table ^word )\n"
    "  find: table ( \\\"<tableNm>\\\" ^w:table ^word ^word )\n"
    "  eql ( \\\"<tableNm>\\\" ^w:table bool )\n"
    "  if\n"
    "    drop ( \\\"<tableNm>\\\" )\n"
    "    true ( \\\"<tableNm>\\\" true )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  drop ( \\\"<tableNm>\\\" )\n"
    "  drop ( )\n"
    "  EC_NOT_A_TABLE false ( errorCode false )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check there is a table folder                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsTableFolder  ( \\\"<tableName>\\\" -- )\n"
    "\n"
    "  findInCurrent not if EC_NO_SUCH_TABLE false exit then\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the table folder and push it onto task dictionary                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushTable ( \\\"<tableName>\\\" -- )\n"
    "\n"
    "  find execute path[].push\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the table folder                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popTable\n"
    "\n"
    "  path[].discard\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a table                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsValidTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if drop EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "  //sTableNm tableInUse if popTable EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // pop table folder\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find table given its name                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::find ( sTableNm -- pTable )\n"
    "\n"
    "  dup \\\"table::find %v\\\" str.format .logNote\n"
    "\n"
    "  find execute\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT db_table.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_Lf.sen

  sFileContents =
    "\""
    "\\\"munged job_Lf.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Lf.sen -- Job list folder                                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Lf.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list folders requests (on originating node)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lf::request _eeh ( -- <R> )\n"
    "\n"
    "  0 0 0 locals| iCount pJob_Lf pTask |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task[] to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_Lf\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR, type VARCHAR)\\\" pJob_Lf job.metadata!\n"
    "  then\n"
    "\n"
    "  \\\"\\\"\n"
    "  path[].currentFolder dic.lastWord dup iterate\n"
    "  1 iCount + to iCount\n"
    "  \\\"row: ('\\\" str.cat\n"
    "\n"
    "  object@ word.name@ str.cat\n"
    "\n"
    "  \\\"', \\\" str.cat\n"
    "\n"
    "  object@ isTable if\n"
    "    \\\"'table'\\\" str.cat\n"
    "  then\n"
    "\n"
    "  object@ isIndex if\n"
    "    \\\"'index'\\\" str.cat\n"
    "  then\n"
    "\n"
    "  object@ isFolder if\n"
    "    \\\"'\\\" str.cat\n"
    "    object@ execute dic.kind@ word.name@ str.cat\n"
    "    \\\"'\\\" str.cat\n"
    "  then\n"
    "\n"
    "  iCount if\n"
    "    \\\")\\\\n\\\" str.cat\n"
    "  then\n"
    "\n"
    "  object@ word.prev object!\n"
    "\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set response in job\n"
    "  pJob_Lf job.response!\n"
    "  iCount pJob_Lf job.rowsProcessed!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: lf :: lf ;\n"
    "\n"
    "jobInfo: lf\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_LOCAL\n"
    "  <rspKind>  = RS_JOB_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_READ\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Lf.sen"_Stz
  ;

  vCompileConstant(sFileContents);


