    "\n"
    "jobInfo: compactIndex\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_DIST2PC\n"
    "  <rspKind>  = RS_PARTICIPANT_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_WRITE\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_CompactIndex.sen"_Stz
  ;

