    "\\\" job_DumpIndex.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a valid table folder                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkDumpIndex ( \\\"<tableNm>\\\" \\\"<indexNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sIndexNm sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "  //sTableNm tableInUse if popTable EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is an index we are dropping\n"
    "  sIndexNm checkIsIndex not if\n"
    "    popIndexes popTable assertInTables false exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes and table folder\n"
    "  popIndexes\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump index request (on originating node)                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dumpIndex_req ( -- <R> )\n"
    "\n"
    "  LogEntry SEED_REQ\n"
    "\n"
    "  0 0 0 0 0 locals| pTask pIndex sTableNm sIndexNm pJob_DumpIndex |\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task[] to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_DumpIndex\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table and index names\n"
    "  //pJob_DumpIndex job.indexName@ to sIndexNm\n"
    "  //pJob_DumpIndex job.objectName@ to sTableNm\n"
    "  <indexNm> to sIndexNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  //check if we can dump the index\n"
    "  sTableNm sIndexNm checkDumpIndex not if pJob_DumpIndex ERROR_REQUEST !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table and indexes folder\n"
    "  sTableNm pushTable assert\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // visualize\n"
    "  sIndexNm find execute index.dump\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes and table folder\n"
    "  popIndexes\n"
    "  popTable\n"
    "\n"
    "  pJob_DumpIndex job.notice\n"
    "\n"
    "  LogExit DONE_REQ\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: dumpIndex :: dumpIndex <tableNm> <indexNm> ;\n"
    "jobSyntax: dumpIndex :: dumpIdx <tableNm> <indexNm> ;\n"
    "\n"
    "jobInfo: dumpIndex\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_LOCAL\n"
    "  <rspKind>  = RS_JOB_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_READ\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_DumpIndex.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_AnalyzeTable.sen

  sFileContents =
    "\""
    "\\\"munged job_AnalyzeTable.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_AnalyzeTable.sen -- Job Analyze Table                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_AnalyzeTable.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a analyzable table folder                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkAnalyzeTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "\n"
    "  // pop table folder\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* analverifyyze table request (on originating node)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeTable::request _eeh ( -- <R> )\n"
    "\n"
    "  \\\"<detailed>\\\" job[] job.enameset@ enameset.hasName not if\n"
    "\n"
    "    \\\"<detailed>\\\" \\\"0\\\" job[] job.enameset@ enameSet.insertStr\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    <detailed> >int 1 == if\n"
    "      \\\"(nodeName VARCHAR, partition INTEGER, buffers INTEGER, bufferLevel VARCHAR, entries INTEGER)\\\"\n"
    "    else\n"
    "      \\\"(nodeName VARCHAR, partition INTEGER, buffers INTEGER, entries INTEGER)\\\"\n"
    "    then\n"
    "    job[] job.metadata!\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_AnalyzeTable job on a node                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeTable::execute _eeh ( -- )\n"
    "\n"
    "  job[] locals| pJob_AnalyzeTable |\n"
    "\n"
    "  0 0 locals| sTableNm bIsDetailed |\n"
    "\n"
    "  \\\"<detailed>\\\" job[] job.enameset@ enameset.hasName not if\n"
    "\n"
    "    \\\"<detailed>\\\" \\\"0\\\" job[] job.enameset@ enameSet.insertStr\n"
    "  then\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table\n"
    "  <tableNm> to sTableNm\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // analyze the table\n"
    "  <detailed> >int sTableNm find execute table.analyze\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // put response in the job\n"
    "  pJob_AnalyzeTable job.response!\n"
    "  grid::slots pJob_AnalyzeTable job.rowsProcessed!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table\n"
    "  popTable\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_AnalyzeTable job check resources                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeTable::checkResources _eeh ( -- )\n"
    "\n"
    "  //\\\"checkResources received\\\" .\n"
    "\n"
    "  \\\"<detailed>\\\" job[] job.enameset@ enameset.hasName not if\n"
    "\n"
    "    \\\"<detailed>\\\" \\\"0\\\" job[] job.enameset@ enameSet.insertStr\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if we can remove the table\n"
    "  <tableNm>\n"
    "  checkAnalyzeTable not if job[] ERROR_JOB !!logError exit then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "jobSyntax: analyzeTable :: analyzeTable <tableNm> ;\n"
    "jobSyntax: analyzeTable :: analyzeTable <tableNm> <detailed> ;\n"
    "jobSyntax: analyzeTable :: antbl <tableNm> ;\n"
    "jobSyntax: analyzeTable :: antbl <tableNm> <detailed> ;\n"
    "\n"
    "jobInfo: analyzeTable\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_DIST2PC\n"
    "  <rspKind>  = RS_PARTICIPANT_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_READ\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_AnalyzeTable.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_upsert.sen

  sFileContents =
    "\""
    "\\\"munged OP_upsert.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_upsert.sen -- Operator upsert                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_upsert.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_CRWBUFFER ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": UpsertOp_CrwBuffer \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_CRWBUFFER\\\" .verbose\n"
    "  Pipein[] to Operand[]\n"
    "  nullptr to Pipein[]\n"
    "\n"
    "  tx[].begin\n"
    "  tablePtn[].get tablePtnGrabWrite2\n"
    "  Operand[].upsertIntoTable\n"
    "  tablePtn[].get tablePtnDropWrite2\n"
    "  tx[].commit\n"
    "  Operand[].delete\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STARTMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": UpsertOp_StartMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STARTMARKER\\\" .verbose\n"
    "  // check if we can insert into the table\n"
    "  <tableNm> op__table if\n"
    "    table[].tablePtn@ to tablePtn[]\n"
    "    Pipein[].pipeout\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STREAMDEF ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": UpsertOp_StreamDef \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STREAMDEF\\\" .verbose\n"
    "  Pipein[].delete\n"
    "  Operand[].newStreamDef\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for upsert                                 (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : UpsertOp_req \\\\operator\n"
    " \n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: UpsertOp_CrwBuffer   ZK_CRWBUFFER   op[].handler!\n"
    "  find: UpsertOp_StartMarker ZK_STARTMARKER op[].handler!\n"
    "  find: UpsertOp_StreamDef   ZK_STREAMDEF   op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: UpsertOp :: UpsertOp <tableNm> ;\n"
    "\n"
    ": UpsertOp opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_upsert.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job2pc.sen

  sFileContents =
    "\""
    "\\\"munged job2pc.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job2pc.sen -- Distributed 2PC Job related words                            */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job2pc.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distribute current originating job to all participating nodes              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::distributeConnected ( -- )\n"
    "\n"
    "  job[] locals| pJob |\n"
    "\n"
    "  // create the response vector in the orginating job to receive responses\n"
    "  pJob job.createResponseVec\n"
    "\n"
    "  // create the buffer queue in the orginating job to receive buffers\n"
    "  pJob job.createBufferQueue\n"
    "\n"
    "  // set the no of acks expected by originator job\n"
    "  //   to be the number of connected nodes in the grid\n"
    "  grid::connectedNodes pJob job.acksRemaining!\n"
    "\n"
    "  // grab this task's lock\n"
    "  task[] task.grabLock\n"
    "\n"
    "  // set acks for originator task\n"
    "  1 task::acks!\n"
    "\n"
    "  // send the job to each connected node in the grid\n"
    "  grid::definedNodes 0 do\n"
    "\n"
    "    I grid::node node.sendSocket@ if\n"
    "      I pJob job.forward\n"
    "    then\n"
    "\n"
    "  loop\n"
    "\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send job__begun back to originating node                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": 2pcReply::job__begun ( -- )\n"
    "\n"
    "  job[] \\\"Job__Begun::send\\\" find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send job__executed back to originating node                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": 2pcReply::job__executed ( -- )\n"
    "\n"
    "  job[] \\\"Job__Executed::send\\\" find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* ended a job on participant node                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": 2pcReply::job__ended ( -- )\n"
    "\n"
    "  job[] \\\"Job__Ended::send\\\" find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancelled a job on participant node                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": 2pcReply::job__cancelled ( -- )\n"
    "\n"
    "  job[] \\\"Job__Cancelled::send\\\" find execute\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job2pc.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_passThru.sen

  sFileContents =
    "\""
    "\\\"munged OP_passThru.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_passThru.sen -- Operator passThru                                       */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_passThru.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_CSVBUFFER ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": PassThru_CsvBuffer \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_CSVBUFFER\\\" .verbose\n"
    "  Counter0[] 1 + to  Counter0[]\n"
    "  Operand[].delete\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_EOSMARKER ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": PassThru_EosMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_EOSMARKER\\\" .verbose\n"
    "  Pipein[].delete\n"
    "  Operand[].newCsvBuffer\n"
    "  Operand[].report\n"
    "  Counter0[] \\\"passThru\\\" \\\"passThru,%v,%v\\\\nn\\\" str.format Operand[].csvAppend\n"
    "  Operand[].pipeout\n"
    "\n"
    "  Operand[].newEosMarker\n"
    "  Operand[].pipeout\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_PULSEMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": PassThru_PulseMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_PULSEMARKER\\\" .verbose\n"
    "  Pipein[].pipeOut\n"
    "\n"
    "  // new a stream def\n"
    "  Operand[].newStreamDef\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STARTMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": PassThru_StartMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STARTMARKER\\\" .verbose\n"
    "\n"
    "  \\\"__REPORT\\\" locals| sReportTable |\n"
    "\n"
    "  sReportTable op__table if\n"
    "    sReportTable pushTable assert\n"
    "    sReportTable find execute to table[]\n"
    "    Pipein[].pipeOut\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for passThru req                           (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : PassThru_req \\\\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  0 to Counter0[]\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: PassThru_CsvBuffer   ZK_CSVBUFFER   op[].handler!\n"
    "  find: PassThru_EosMarker   ZK_EOSMARKER   op[].handler!\n"
    "  find: PassThru_PulseMarker ZK_PULSEMARKER op[].handler!\n"
    "  find: PassThru_StartMarker ZK_STARTMARKER op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: PassThru :: PassThru ;\n"
    "\n"
    ": PassThru opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_passThru.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_nodeInfo.sen

  sFileContents =
    "\""
    "\\\"munged OP_nodeInfo.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_nodeInfo.sen -- Operator node info                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_nodeInfo.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": nodeInfo_action\n"
    "\n"
    "  0 locals| iRowSize |\n"
    "\n"
    "  // get row size from streamDef\n"
    "  StreamDef[].rowSize to iRowSize\n"
    "\n"
    "  // create an infoSet operand\n"
    "  iRowSize InfoSet[].newInfoSet\n"
    "\n"
    "  // add nodeInfo to the infoSet\n"
    "  StreamDef[] InfoSet[].addNodeInfo assert\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  StreamDef[].pipeout\n"
    "\n"
    "  // pipeout the infoset\n"
    "  InfoSet[].pipeout\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: NodeInfo :: NodeInfo ;\n"
    "\n"
    ": nodeInfo opInfo tagCopy: liteOp_tags\n"
    "tags{\n"
    "  <jobDesc>   = \\\"--description of operator--\\\"\n"
    "  <liteOp>    = true\n"
    "  <streamDef> = __nodeInfo\n"
    "  }\n"
    " ;\n"
    "  \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_nodeInfo.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_ConnectCluster.sen

  sFileContents =
    "\""
    "\\\"munged job_ConnectCluster.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_ConnectCluster.sen -- Job Connect Cluster                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_ConnectCluster.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": node.isConnected ( pNode -- t|f )\n"
    "\n"
    "  params| pNode |\n"
    "\n"
    "  pNode node.sendSocket@ if\n"
    "    true\n"
    "  else\n"
    "    false\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::connected ( -- t|f )\n"
    "\n"
    "  grid::definedNodes 0\n"
    "  do\n"
    "    I grid::node node.isConnected not if\n"
    "      args.verbose if\n"
    "        I \\\"Node no %v not connected\\\" .printf\n"
    "      then\n"
    "      unloop\n"
    "      false\n"
    "      exit\n"
    "    then\n"
    "  loop\n"
    "\n"
    "  \\\"All nodes connected\\\" .verbose\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::pause ( -- )\n"
    "\n"
    "  begin\n"
    "    grid::connected not\n"
    "  while\n"
    "    100 thread::sleepMsec\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gridTest\n"
    "\n"
    "  grid::definedNodes 0\n"
    "  do\n"
    "    I grid::node node.isConnected\n"
    "    I \\\"gridTest: node no %v connected %v \\\" .printf\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gridWait\n"
    "\n"
    "  grid::pause\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request to wait for cluster to connect (on originating node)               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": connectCluster_req ( -- <R> )\n"
    "\n"
    "\n"
    "  task::seedInitially\n"
    "\n"
    "  // [ compiler::current@ word.name@ , ] .\n"
    "  // <jobNm> .\n"
    "\n"
    "  job::becomeOriginator\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // has cluster already been started?\n"
    "\n"
    "  grid::started@ if\n"
    "                                             //! how do we set an error message?\n"
    "    DONE_REQ\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // spawn all other nodes\n"
    "\n"
    "  grid::setStartNode\n"
    "\n"
    "  //grid::spawnOtherNodes\n"
    "\n"
    "  //connector::spawn\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pause till all nodes connected\n"
    "\n"
    "  grid::pause\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the start cluster job\n"
    "\n"
    "  job::distributeConnected\n"
    "\n"
    "  // wait for the signal from deciding job__ended/cancelled\n"
    "  task::wait\n"
    "\n"
    "  // set grid as started\n"
    "  true grid::started!\n"
    "  \\\"Cluster started\\\" .\n"
    "\n"
    "  task::doneFinally\n"
    "\n"
    "  //\\\"Signalling waiting thread\\\" .\n"
    "  job[] job.signalWaiter\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute job_ConnectCluster (on participating node)                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": connectCluster::execute _eeh ( -- )\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // wait till all nodes connected\n"
    "  grid::pause\n"
    "\n"
    "  true grid::started!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: connectCluster :: connectCluster ;\n"
    "\n"
    "jobInfo: connectCluster\n"
    "{\n"
    "  <jobKind>  = JK_DIST2PC\n"
    "  <rspKind>  = RS_NONE\n"
    "  <ddlLock>  = DL_NONE\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\""
  " CONSTANT job_ConnectCluster.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job__Ended.sen

  sFileContents =
    "\""
    "\\\"munged job__Ended.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job__Ended.sen -- generic job related words                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job__Ended.sen\\\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on participating node                           //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send Job__Ended back to originating node                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__Ended::send ( pJobParticipant -- )\n"
    "\n"
    "  params| pJobParticipant |\n"
    "\n"
    "  pJobParticipant job.id@ locals| iJobId |\n"
    "\n"
    "  0 locals| pJob__Ended |\n"
    "\n"
    "  // new a temporary Job__Ended\n"
    "  pJobParticipant job__Ended::new to pJob__Ended\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // set the originator node as the send target node\n"
    "  //iJobId job::originator@ grid::node task[] task.sendNode!\n"
    "\n"
    "  // send the ended job\n"
    "  iJobId job::originator@ pJob__Ended job.reply\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  pJob__Ended job.delete\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on originating node                             //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* run received Job__Ended on originating node                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _Ended _run\n"
    "\n"
    "  job[] locals| pJob__Ended |\n"
    "  pJob__Ended job.id@ locals| iJobId |\n"
    "\n"
    "  0 locals| bAmDecider |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the context of this __ended job\n"
    "\n"
    "  // find the originating job\n"
    "  iJobId olist::findJob drop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // process __ended job on this originating node\n"
    "\n"
    "  // increment the number of __ended jobs received in api state\n"
    "  JobRef[] ssn::incEnded\n"
    "  JobRef[] ssn::traceSession\n"
    "\n"
    "  // decrement the acks remaining\n"
    "  JobRef[] job.dec2pcAcksRmg to bAmDecider\n"
    "\n"
    "  // if there are acks remaining just exit\n"
    "  bAmDecider not if\n"
    "    JobRef[].return\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // all __ended jobs have been received, so this job is the decider\n"
    "\n"
    "  // remove the originating job from the originator jobs\n"
    "  JobRef[] job.removeOriginator\n"
    "\n"
    "  JP_ENDED log::markPhase\n"
    "\n"
    "  // notify the originating task\n"
    "  //JobRef[] job.originatingTask@ task.ack\n"
    "  JobRef[] job.task@ task.ack\n"
    "  JobRef[].return\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: _Ended :: _Ended ;\n"
    "\n"
    "jobInfo: _Ended\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_GENERIC\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job__Ended.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of db_partition.sen

  sFileContents =
    "\""
    "\\\"munged db_partition.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_partition.sen -- partition related words                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" db_partition.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a partitions folder under given named table                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makePartitions ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  params| tableNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    tableNm \\\"MAKING PARTITIONS FOR TABLE \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tableNm find execute ( dic )\n"
    "  \\\"partitions\\\" ( dic \\\"partitions\\\" )\n"
    "  swap         ( \\\"partitions\\\" dic )\n"
    "  :subFolder   ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within partitions folder                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinPartitions\n"
    "  path[].currentFolder dic.name \\\"partitions\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in partitions folder                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInPartitions\n"
    "  withinPartitions if true exit then\n"
    "  EC_NOT_IN_PARTITIONS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the partitions folder and push it onto task dictionary                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushPartitions ( -- )\n"
    "  \\\"partitions\\\" find execute path[].push\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the partitions folder                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popPartitions\n"
    "  path[].discard\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the partition sub folder and push it onto task dictionary             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": pushPartitionSub ( \\\"<tableNm>\\\" -- )\n"
    "  find execute table.slots slots.subDic path[].push\n"
    "  true\n"
    " ;\n"
    "*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the partition sub folder                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popPartitionSub\n"
    "  path[].discard\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* assert top of task dictionary stack is partitions                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertInPartitions ( -- t|f )\n"
    "  withinPartitions assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* tidy up of the partition                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": partitionTidyUp ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "   find execute ( ^tablePtr )\n"
    "   \n"
    "   // forget all column names\n"
    "   dup table.slots slots.subDic\n"
    "   path[].push\n"
    "   \\\"columns\\\" find execute forgetAll\n"
    "   path[].discard\n"
    "\n"
    "  // forget the sub dictionary\n"
    "  table.slots slots.subDic forgetAll\n"
    " ;\n"
    "*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* grab read lock on a partition of given table                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnGrabRead ( i_Partition pTable -- )\n"
    "\n"
    "  params| pTable |      // given table\n"
    "  params| i_Partition | // which partition\n"
    "\n"
    "  begin\n"
    "    i_Partition pTable table.getPtn tablePtn.attemptGrabRead\n"
    "    not while\n"
    "      task::yield\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* grab write lock on a partition of given table                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnGrabWrite ( i_Partition pTable -- )\n"
    "\n"
    "  params| pTable |      // given table\n"
    "  params| i_Partition | // which partition\n"
    "\n"
    "  begin\n"
    "    i_Partition pTable table.getPtn tablePtn.attemptGrabWrite\n"
    "    not while\n"
    "      task::yield\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* grab write lock on a partition of given table                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnGrabWrite2 ( pTablePtn -- )\n"
    "\n"
    "  params| pTablePtn |   // table partition\n"
    "\n"
    "  begin\n"
    "    pTablePtn tablePtn.attemptGrabWrite\n"
    "  not while\n"
    "    task::yield\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* grab read lock on a partition of given table                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnGrabRead2 ( pTablePtn -- )\n"
    "\n"
    "  params| pTablePtn |   // table partition\n"
    "\n"
    "  begin\n"
    "    pTablePtn tablePtn.attemptGrabRead\n"
    "  not while\n"
    "    task::yield\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop read lock on a partition of given table                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnDropRead ( i_Partition pTable -- )\n"
    "\n"
    "  params| pTable |      // given table\n"
    "  params| i_Partition | // which partition\n"
    "\n"
    "  i_Partition pTable table.getPtn tablePtn.dropRead\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop write lock on a partition of given table                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnDropWrite ( i_Partition pTable -- )\n"
    "\n"
    "  params| pTable |      // given table\n"
    "  params| i_Partition | // which partition\n"
    "\n"
    "  i_Partition pTable table.getPtn tablePtn.dropWrite\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop read lock on a partition of given table                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnDropRead2 ( pTablePtn -- )\n"
    "\n"
    "  params| pTablePtn |  // given tablePtn\n"
    "\n"
    "  pTablePtn tablePtn.dropRead\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop write lock on a partition of given table                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnDropWrite2 ( pTablePtn -- )\n"
    "\n"
    "  params| pTablePtn |  // given tablePtn\n"
    "\n"
    "  pTablePtn tablePtn.dropWrite\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT db_partition.sen"_Stz
  ;

  vCompileConstant(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of task.sen

  sFileContents =
    "\""
    "\\\"munged task.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* task.sen -- task ipc primitives                                            */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" task.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set the number of acks the task will wait for                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": task::acks! ( nAcks -- )\n"
    "\n"
    "  task[] task.acks!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get this tasks send socket                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": task::sendSocket@\n"
    "\n"
    "  task[] task.sendNode@ node.sendSocket@\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* grab lock on the tasks send socket                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": task::socketLock ( -- )\n"
    "\n"
    "  task[] task.sendNode@ node.sendSocket@ socket.grabWrite\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop lock on the tasks send socket                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": task::socketUnlock ( -- )\n"
    "\n"
    "  task[] task.sendNode@ node.sendSocket@ socket.dropWrite\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT task.sen"_Stz
  ;

  vCompileConstant(sFileContents);


