  sFileContents =
    "\""
    "\\\"munged db_tenant.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_tenant.sen -- tenant related words                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" db_tenant.sen\\\" .verbose\n"
    "\n"
    ": tenant ;\n"
    "\n"
    ": :tenant\n"
    "    :createFolder\n"
    "         //dup find: tenant swap word.category!\n"
    "         dup find: tenant swap execute dic.kind!\n"
    " ;\n"
    "\n"
    ": withinTenants\n"
    "    path[].currentFolder dic.name \\\"tenants\\\" str.equal\n"
    " ;\n"
    "\n"
    ": checkInTenants\n"
    "    withinTenants if true exit then\n"
    "    EC_NOT_IN_TENANTS false\n"
    " ;\n"
    "/*\n"
    ": checkIsTenant ( word )\n"
    "\n"
    "    dup word.category@ find: \\\\folder eql if true exit then\n"
    "    dup execute dic.kind@ find: tenant eql if true exit then\n"
    "    drop\n"
    "    EC_NOT_A_TENANT false\n"
    " ;\n"
    "*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a tenant folder                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsTenant ( word )\n"
    "\n"
    "  dup word.category@ find: \\\\folder eql not if EC_NOT_A_FOLDER false exit then\n"
    "  dup execute dic.kind@ find: tenant eql if true exit then\n"
    "  EC_NOT_A_TENANT false\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT db_tenant.sen"_Stz
  ;

