    ": chuck4 prompt rstk 0 1 2 3 stk throw ;\n"
    ": chuck5 prompt rstk 0 1 2 3 stk path[].dump throw ;\n"
    "\n"
    "// - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    ": iftest if \\\"yes\\\" . then ;\n"
    "\n"
    ": ifelsetest if \\\"yes\\\" . else \\\"no\\\" . then ;\n"
    "\n"
    ": untiltest 0 begin 1 + dup . dup 10 == until ;\n"
    "\n"
    ": whiletest 0 begin 1 + dup 10 < while dup . repeat ;\n"
    "\n"
    ": dotest 10 0 do I . loop ;\n"
    ": ?dotest 10 0 ?do I . loop 10 10 ?do I . loop ;\n"
    "\n"
    ": +looptest 10 0 do I . 2 +loop ;\n"
    "\n"
    ": iterateTest\n"
    "    compiler::current@ compiler::current@ iterate // iterate word cursor\n"
    "      object@ word.name@ .       // print the name of the word\n"
    "      object@ word.prev object! // step backwards thru words\n"
    "    next                        // next iteration\n"
    " ;\n"
    "\n"
    ": string_blowup\n"
    "\n"
    "traceon\n"
    "    \\\"abcdefghijklmnopqrstuvwxyz\\\"\n"
    "    1000000 0 do\n"
    "      \\\"abcdefghijklmnopqrstuvwxyz\\\"\n"
    "      str.cat\n"
    "    loop\n"
    " ;\n"
    "\n"
    ": rottest\n"
    "\n"
    "  2 1 0 rot . . .\n"
    " ;\n"
    "\n"
    ": invrottest\n"
    "\n"
    "  2 1 0 -rot . . .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* str.format testing                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": strFormatTest\n"
    "\n"
    "  1 \\\"abc%v\\\" str.format .\n"
    "\n"
    "  \\\"def\\\" \\\"abc%v\\\" str.format .\n"
    "\n"
    "  \\\"gh\\\" 456 \\\"def\\\" 23 \\\"abc\\\" 1\n"
    "  \\\"%v %v %v %v %v %v\\\" str.format .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* locals testing                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lt\n"
    "\n"
    "  789 456 123 locals| a b c |\n"
    "\n"
    "  a . b . c .\n"
    "\n"
    "  321 to a\n"
    "  654 to b\n"
    "  789 to c \n"
    "\n"
    "  a . b . c .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* postpone testing                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": callTest immediate\n"
    "\n"
    "  test\n"
    " ;\n"
    "\n"
    ": postponeTest\n"
    "\n"
    "  postpone callTest\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* string replacement                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": srepl\n"
    "\n"
    "  \\\"this\\\" \\\"that\\\" \\\"abcthisdef\\\" str.replace .\n"
    "\n"
    "  \\\"this\\\" \\\"that\\\" \\\"abcthidef\\\" str.replace .\n"
    "\n"
    "  \\\"this\\\" \\\"that\\\" \\\"abcthisdefthis\\\" str.replace .\n"
    "  \\\"this\\\" \\\"that\\\" \\\"abcthisthisdefthis\\\" str.replace .\n"
    "  \\\"this\\\" \\\"that\\\" \\\"thisthiabcthisthisdefthis\\\" str.replace .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": whereAmI\n"
    "\n"
    "  \\\"whereAmI?\\\" .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* locks                                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": locksReset\n"
    "  lockTracker::reset\n"
    " ;\n"
    "\n"
    ": locksList\n"
    "  lockTracker::list\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* yield testing                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": yieldTest\n"
    "\n"
    "  10 0 do\n"
    "    I .\n"
    "    task::yield\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* unknown word during boot                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": unknownDuringBoot\n"
    "\n"
    "  // anUnknownWord\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test task sleep                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": testSleep\n"
    "\n"
    "  0 0 locals| sleepTime |\n"
    "\n"
    "  10 0 do\n"
    "    I to sleepTime\n"
    "    time.current \\\"start time %v\\\" str.format .\n"
    "    sleepTime \\\"task sleeping for %v secs\\\" str.format .\n"
    "    1000000 sleepTime * task::sleepUsec\n"
    "    time.current \\\"end time %v\\\\n\\\" str.format .\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test reverse                                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": testReverse prompt\n"
    "\n"
    "  1 2 3 . . .\n"
    "  1 2 3 3 reverse . . .\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test store strings into session todo                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ssnDo\n"
    "\n"
    "  \\\"storedCmd\\\" :create\n"
    "\n"
    "  true compiler::current@ word.prompt!\n"
    "\n"
    "  \\\"print \\\\\\\"hello world!\\\\\\\"\\\" encode::push\n"
    "\n"
    "  POSTPONE session::this\n"
    "\n"
    "  POSTPONE session.todo!\n"
    "\n"
    "  POSTPONE exit_rt\n"
    " ;\n"
    "\n"
    "//debug::breakPoint\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT test_misc.sen"_Stz
  ;

