  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_CreateTable.sen

  sFileContents =
    "\""
    "\\\"munged job_CreateTable.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_CreateTable.sen -- Job Create Table                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_CreateTable.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is not a table                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsNotTable ( \\\"<wordNm>\\\" -- t|f )\n"
    "  findInCurrent not if true exit then\n"
    "  EC_TABLE_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a makeable table                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkMakeTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  checkInTables   not if false exit then\n"
    "  checkIsNotTable not if false exit then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a table (run by all participants)                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTable ( \\\"<tableNm>\\\" )\n"
    "\n"
    "\n"
    "  params| sTableNm |\n"
    "  0 0 locals| pTable pIndex |\n"
    "\n"
    "  args.tracepoint if\n"
    "    sTableNm \\\"MAKING TABLE \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // make the table dictionary\n"
    "  sTableNm makeTableDic\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // make the indexes dictionary\n"
    "  sTableNm pushTable assert\n"
    "  sTableNm \\\"makeIndexes\\\" find execute\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // create the table\n"
    "  sTableNm :table ( ^table ) drop\n"
    "  sTableNm find execute to pTable\n"
    "\n"
    "  // return table pointer\n"
    "  pTable\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create table request (on originating node)                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": createTable::request _eeh ( -- <R> )\n"
    "\n"
    "  job[] locals| pJob_CreateTable |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check create index syntax\n"
    "  <cmd> TableDef::syntax dup EC_NONE != if\n"
    "    pJob_CreateTable ERROR_JOB !!logError\n"
    "  else\n"
    "    drop\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_CreateTable job on each node                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": createTable::execute _eeh ( -- )\n"
    "\n"
    "  job[] locals| pJob_CreateTable |\n"
    "\n"
    "  0 locals| pTable |\n"
    "\n"
    "  //!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n"
    "  <cmd> pJob_CreateTable tableDef::parse locals| pTableDef |\n"
    "  //!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // check for error while creating tabledef\n"
    "  grid::thisNode@ pJob_CreateTable job.hasError if\n"
    "    pJob_CreateTable DdlLock[].testDrop !!logError exit then\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // make table\n"
    "  <tableNm> makeTable to pTable\n"
    "\n"
    "  //!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n"
    "  pTableDef pTable table.tableDef!\n"
    "  //!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // add partition columns\n"
    "  pTable table.slots slots.createStreamDef\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // move back to tables\n"
    "  popTable\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // should be in tables\n"
    "  assertInTables\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_CreateTable job check resources                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": createTable::checkResources _eeh ( -- )\n"
    "\n"
    "  //\\\"checkResources received\\\" .\n"
    "\n"
    "  job[] locals| pJob_CreateTable |\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // grab a ddl lock\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // check if we have enough buffers\n"
    "  node::checkEnoughBuffers not if pJob_CreateTable ERROR_JOB !!logError exit then\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // check if we can make the table\n"
    "  //pJob_CreateTable job.objectName@\n"
    "  <tableNm> checkMakeTable not if pJob_CreateTable ERROR_JOB !!logError exit then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "jobSyntax: createTable :: create table <tableNm> etc ;\n"
    "jobSyntax: createTable :: create table definition <tableNm> etc ;\n"
    "\n"
    "jobInfo: createTable\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_DIST2PC\n"
    "  <rspKind>  = RS_PARTICIPANT_RESPONSE\n"
    "  <ddlLock>  = DL_GRAB_WRITE\n"
    "  \n"
    "  <preCheck> = bClusterStarted\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_CreateTable.sen"_Stz
  ;

  vCompileConstant(sFileContents);


