  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_snapshot.sen

  sFileContents =
    "\""
    "\\\"munged OP_snapshot.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_snapshot.sen -- Operator snapshot                                       */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_snapshot.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_PULSEMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Snapshot_PulseMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_PULSEMARKER\\\" .verbose\n"
    "  Pipein[].pipeOut\n"
    "\n"
    "  // new a stream def\n"
    "  Operand[].newStreamDef\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  // grab a read lock onn the table ptn\n"
    "  tablePtn[].get tablePtnGrabRead2\n"
    "\n"
    "  // begin a read transaction\n"
    "  tx[].begin\n"
    "\n"
    "  // pipeout all subsets from tablePtn\n"
    "  tablePtn[].root to Subset[]\n"
    "  Subset[]@ to Operand[]\n"
    "  begin\n"
    "    Operand[].isNull\n"
    "  not while\n"
    "    Operand[].get crwBuffer.snapshot Op::pipeOut\n"
    "    nullptr Operand[].set\n"
    "    Subset[].nextBuffer to Operand[]\n"
    "  repeat\n"
    "\n"
    "  // end a read transaction\n"
    "  tx[].commit\n"
    "\n"
    "  // drop the read lock on the table ptn\n"
    "  tablePtn[].get tablePtnDropRead2\n"
    "\n"
    "  Operand[].newEosMarker\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STARTMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Snapshot_StartMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STARTMARKER\\\" .verbose\n"
    "\n"
    "  // check if we can scan the table\n"
    "  <tableNm> op__table if\n"
    "    table[].tablePtn@ to tablePtn[]\n"
    "    Pipein[].pipeOut\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* Snapshot request                                   (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Snapshot_req \\\\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: Snapshot_PulseMarker ZK_PULSEMARKER op[].handler!\n"
    "  find: Snapshot_StartMarker ZK_STARTMARKER op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: Snapshot :: Snapshot <tableNm> ;\n"
    "\n"
    ": Snapshot opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_snapshot.sen"_Stz
  ;

  vCompileConstant(sFileContents);


