  // munge of vocab_useful.sen

  sFileContents =
    "\""
    "\\\"munged vocab_useful.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* vocab_useful.sen -- misc useful stuff                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" vocab_useful.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* snooze briefly                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": snooze ( -- )\n"
    "\n"
    "  C_1M thread::sleepNsec\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* put task into infinite snooze loop                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": snoozeLoop\n"
    "\n"
    "  begin\n"
    "    \\\"snoozing...\\\" . snooze task::yield\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* hello world                                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": helloWorld\n"
    "\n"
    "  \\\"Hello World!\\\" .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* print arg                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": printArg\n"
    "\n"
    "  .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* conver into into a string of digit names                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >digitWords ( i -- s )\n"
    "\n"
    "  >str locals| sDecodeMe |\n"
    "\n"
    "  \\\"\\\" \\\"\\\" 0 locals| iDigit sDigitName sDecodedTo |\n"
    "\n"
    "  // loop for 0 to length of sDecodeMe - 1\n"
    "  sDecodeMe str.length 0\n"
    "  do\n"
    "    // concat \\\" \\\" to end of decoded string\n"
    "    I if sDecodedTo \\\" \\\" str.cat to sDecodedTo then\n"
    "\n"
    "    // clip out digit I, convert it to a str\n"
    "    1 I sDecodeMe str.sub >int >digitName to sDigitName\n"
    "\n"
    "    // append digit name to the decoded string\n"
    "    sDecodedTo sDigitName str.cat to sDecodedTo\n"
    "  loop\n"
    "\n"
    "  // return decode string\n"
    "  sDecodedTo\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* formatted print                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fmt.print\n"
    "\n"
    "  str.format .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* formatted print     https://en.wikipedia.org/wiki/Printf_format_string     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .printf\n"
    "\n"
    "  str.format .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* formatted put                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fmt.put\n"
    "\n"
    "  str.format .put\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* stack should have zero values                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertStackDepthZero\n"
    "\n"
    "  depth 0 == if exit_rt then\n"
    "\n"
    "  task[] task.name@ \\\"Stack of task %v has grown\\\" .printf\n"
    "\n"
    "  debug::trap\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* include a sub dir of sen files                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": include-subdir\n"
    "\n"
    "  params| sSubDir |\n"
    "\n"
    "  0 locals| sFilePath |\n"
    "\n"
    "  input::push\n"
    "\n"
    "  args.senDir sSubDir str.cat dup\n"
    "\n"
    "  \\\"Would include .sen files from sub-dir %v\\\" .printf\n"
    "\n"
    "  dir::new locals| pSubDir |\n"
    "\n"
    "  pSubDir dir.open if\n"
    "\n"
    "    begin\n"
    "      pSubDir dir.read\n"
    "    while\n"
    "      pSubDir dir.entryName \\\"Entry %v\\\" .printf\n"
    "\n"
    "      4 pSubDir dir.entryName str.right \\\".sen\\\" str.equal if\n"
    "        pSubDir dir.entryName \\\"Would parse %v\\\" .printf\n"
    "\n"
    "        args.senDir sSubDir str.cat\n"
    "          \\\"/\\\" str.cat\n"
    "          pSubDir dir.entryName str.cat\n"
    "          to sFilePath\n"
    "        sFilePath \\\"Would open %v\\\" .printf\n"
    "\n"
    "        sFilePath input::open interpret input::close\n"
    "\n"
    "      then\n"
    "\n"
    "    repeat\n"
    "\n"
    "    pSubDir dir.close\n"
    "  then\n"
    "\n"
    "  pSubDir dir.delete\n"
    "\n"
    "  input::pop\n"
    "\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT vocab_useful.sen"_Stz
  ;

  vCompileConstant(sFileContents);


